function planetTypeFor(p){return PLANET_TYPES.find(t=>t.id===p?.planetType)||RETIRED_WORLD_TYPES.find(t=>t.id===p?.planetType)||PLANET_TYPES[0];}
function planetBasePopulation(p){return planetTypeFor(p).basePopulation;}
function rollPlanetType(previous){const choices=PLANET_TYPES.filter(p=>p.id!==previous);return choices[Math.min(choices.length-1,Math.floor(Math.random()*choices.length))];}
