const SHIP_CLASS_TARGET={Fi:'Fighter',Co:'Corvette',Fr:'Frigate',De:'Destroyer',Cr:'Cruiser',Bs:'Battleship'};
function shipFromRow(row){const [race,name,shipClass,t1,t2,t3,type,cloaked,initiative,guns,armour,damage,er,metal,crystal,eonium,ac,dc,eta]=row;const id=`${race.toLowerCase()}-${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;return [id,{id,race,name,icon:{Fighter:'✧',Corvette:'⌁',Frigate:'⬡',Destroyer:'◈',Cruiser:'◉',Battleship:'⬢'}[shipClass],class:shipClass,targetSlots:[t1,t2,t3].map(t=>t==='-'?'':SHIP_CLASS_TARGET[t]||t),target:[t1,t2,t3].filter(x=>x!=='-').map(x=>SHIP_CLASS_TARGET[x]||x),type,cloaked:cloaked==='Y',initiative,guns,armour,damage:damage==='-'?0:damage,populationDamage:['Cruiser','Battleship'].includes(shipClass)?0.1:null,populationDamageUnit:'percent',er,cost:{metal,crystal,eonium},ac,dc,eta,pod:type==='Pod'||type==='Steal',factory:['Fighter','Corvette'].includes(shipClass)?'lightFactory':['Frigate','Destroyer'].includes(shipClass)?'mediumFactory':'heavyFactory',research:{Fighter:'fighter',Corvette:'corvette',Frigate:'frigate',Destroyer:'destroyer',Cruiser:'destroyer',Battleship:'siege'}[shipClass]}];}
const SHIP_BASELINE=Object.fromEntries(SHIP_CATALOG.map(shipFromRow));
const SHIPS=JSON.parse(JSON.stringify(SHIP_BASELINE));
function loadOfficialShipStats(){for(const id of Object.keys(SHIPS)){delete SHIPS[id];}Object.assign(SHIPS,JSON.parse(JSON.stringify(SHIP_BASELINE)));}
function applyShipStatOverrides(){const migrated={};for(const [id,values] of Object.entries(state.shipStatOverrides||{})){const key=LEGACY_SHIP_MAP[id]||id;if(!SHIPS[key])continue;if(values.populationDamage!==undefined&&values.populationDamage!==null&&values.populationDamageUnit!=='percent'){values.populationDamage=Math.max(0,Math.min(100,Number(values.populationDamage)/10));values.populationDamageUnit='percent';}migrated[key]={...(migrated[key]||{}),...values,cost:{...(migrated[key]?.cost||{}),...(values.cost||{})}};Object.assign(SHIPS[key],migrated[key],{cost:{...SHIPS[key].cost,...migrated[key].cost}});}for(const ship of Object.values(SHIPS))ship.factory=["Fighter","Corvette"].includes(ship.class)?"lightFactory":["Frigate","Destroyer"].includes(ship.class)?"mediumFactory":"heavyFactory";state.shipStatOverrides=migrated;}

