function normalizeConstructionOrders(){for(const order of [state.construction,...state.constructionQueue].filter(Boolean)){if(order.workFormulaVersion===2)continue;const expected=BUILDINGS[order.id]?.cu;if(expected>0&&Number(order.total)>0){const fraction=Math.max(0,Math.min(1,Number(order.remaining)/Number(order.total)));order.total=expected;order.remaining=expected*fraction;}order.workFormulaVersion=2;}}
