function normalizeProductionOrder(order){if(!order)return order;if(order.formulaVersion===2&&order.factoryWork)return order;const oldTotal=Math.max(0,Number(order.total)||0),fraction=oldTotal?Math.max(0,Math.min(1,Number(order.remaining)/oldTotal)):1,items=productionOrderItems(order),weights={};for(const item of items){const ship=SHIPS[item.id];if(!ship)continue;const factory=['Fighter','Corvette'].includes(ship.class)?'lightFactory':['Frigate','Destroyer'].includes(ship.class)?'mediumFactory':'heavyFactory';weights[factory]=(weights[factory]||0)+Object.values(ship.cost).reduce((n,v)=>n+v,0)*item.qty;}if(order.paidFactoryCosts){for(const key of Object.keys(weights))weights[key]=Math.max(0,Number(order.paidFactoryCosts[key])||0);}const weightTotal=Object.values(weights).reduce((n,v)=>n+v,0),paid=Object.values(order.cost||{}).reduce((n,v)=>n+(Number(v)||0),0)||oldTotal;order.factoryAssignments=order.factoryAssignments||copy(state.factoryAssignments||{});order.factoryWork={};for(const [factory,weight]of Object.entries(weights)){const resourceCost=weightTotal?paid*weight/weightTotal:0,count=productionFactoryCount(factory,order),total=productionUnitWork(resourceCost)+10000*count;order.factoryWork[factory]={total,remaining:total*fraction,preparedFactories:count,resourceCost};}order.formulaVersion=2;refreshProductionTotals(order);return order;}
