function researchRate(){const labs=Math.max(0,state.buildings.researchLab||0),total=Object.values(state.buildings).reduce((a,b)=>a+b,0)||1,labBonus=Math.min(20,100*labs/total),multiplier=Number.isFinite(Number(state.config?.researchMultiplier))?Math.max(0,Number(state.config.researchMultiplier)):1;return Math.max(0,Math.floor(raceWorkRates().rp*(1+(workforceRate('research')+labBonus+governmentEconomyBonus('research'))/100)*multiplier))+populationProductionBonus();}
function constructionRate(){return Math.max(0,Math.floor(raceWorkRates().cu*(1+(workforceRate('construction')+governmentEconomyBonus('construction'))/100)))+populationProductionBonus();}
const GOVERNMENTS={None:{production:0,cost:0},Corporatism:{production:0,cost:0},Democracy:{production:0,cost:8},Nationalism:{production:-10,cost:0},Socialism:{production:20,cost:0},Totalitarianism:{production:-10,cost:6},Anarchy:{production:-20,cost:0}};
function currentGovernmentName(){return state.governmentPending?(state.tick<state.governmentRevolutionUntil?'Anarchy':state.governmentPending):(state.government||'None');}
function governmentProduction(){return GOVERNMENTS[currentGovernmentName()]||GOVERNMENTS.None;}
function productionBonusBreakdown(){const population=Math.max(0,Math.min(100,workforceRate('shipwright'))),government=governmentProduction().production,race=raceWorkRates().production;return {population,government,race,multiplier:Math.max(0,1+(population+government+race)/100)};}
function productionRate(order=state.production){if(order){normalizeProductionOrder(order);return Object.keys(order.factoryWork).reduce((sum,id)=>sum+factoryProductionRate(id,order),0);}return Object.keys(FACTORY_WEIGHTS).reduce((sum,id)=>sum+factoryProductionRate(id,null),0);}
function shipProductionCost(id){const discount=governmentProduction().cost,worldDiscount=planetTypeFor(state).shipCostDiscountPercent||0;return Object.fromEntries(Object.entries(SHIPS[id].cost).map(([r,n])=>[r,Math.ceil(n*(1-discount/100)*(1-worldDiscount/100))]));}
function productionBonusHTML(){const bonus=productionBonusBreakdown();return '<div class="production-bonus-note"><b>LIVE ORDER BONUSES</b><span>Population / shipwrights: +'+bonus.population+'%</span><span>Government: '+esc(currentGovernmentName())+' · '+(bonus.government>=0?'+':'')+bonus.government+'%</span><span>Race output: +'+bonus.race+'%</span><span>Combined output: '+Math.round(bonus.multiplier*100)+'% of base</span><small>Changes apply immediately to running orders. Factory allocation uses Apply to order #. Paid resource costs stay fixed.</small><a href="/manual.html#governments">Government lookup →</a></div>';}
function governmentHTML(){return '<section class="panel" style="margin-top:14px"><div class="ph"><div class="pt">GOVERNMENT · ECONOMY & PRODUCTION</div><span class="meta">'+esc(currentGovernmentName())+'</span></div><div class="controls"><div class="field"><label for="governmentSelect">Planet government</label><select id="governmentSelect" '+(state.governmentPending&&state.tick<state.governmentRevolutionUntil?'disabled':'')+'>'+Object.keys(GOVERNMENTS).filter(n=>n!=='Anarchy').map(n=>'<option '+(n===(state.governmentPending||state.government||'None')?'selected':'')+'>'+n+'</option>').join('')+'</select></div><button class="btn primary" data-save-government>APPLY GOVERNMENT</button><a class="btn" href="/manual.html#governments">GOVERNMENT LOOKUP</a></div>'+productionBonusHTML()+'<div class="controls"><span class="tag">MINING '+governmentEconomyBonus('mining')+'%</span><span class="tag">RESEARCH '+governmentEconomyBonus('research')+'%</span><span class="tag">CONSTRUCTION '+governmentEconomyBonus('construction')+'%</span></div><div class="note" style="margin:12px">'+(state.governmentPending&&state.tick<state.governmentRevolutionUntil?'Revolution: '+(state.governmentRevolutionUntil-state.tick)+' ticks remaining. Production uses the Anarchy penalty until '+esc(state.governmentPending)+' takes over.':'First government formation is free within the first 168 ticks. Changing government starts a 72-tick revolution.')+'</div></section>';}
function saveGovernment(){const name=document.getElementById('governmentSelect')?.value;if(!GOVERNMENTS[name]||name==='Anarchy')return;if(state.governmentPending&&state.tick<state.governmentRevolutionUntil)return notify('Wait for the current revolution to finish.',true);const current=currentGovernmentName();if(name===current)return notify('That government is already active.');if(name==='None')return notify('Select one of the five government types.',true);if(current==='None'&&state.tick<=168){state.government=name;state.governmentPending=null;state.governmentRevolutionUntil=0;}else{if(!confirm('Changing government starts 72 ticks of revolution with the Anarchy production penalty. Continue?'))return;state.governmentPending=name;state.governmentRevolutionUntil=state.tick+72;}const home=state.galaxy.find(p=>p.player);if(home){home.government=state.government||'None';home.governmentPending=state.governmentPending||null;home.governmentRevolutionUntil=state.governmentRevolutionUntil||0;}addNews('Government selection: '+name+'. Production bonuses now follow '+currentGovernmentName()+'.','info');update();notify('Government settings applied.');}

function costAsteroids(start,qty){let n=0;for(let i=0;i<qty;i++){const x=start+i;n+=Math.ceil(2.5*(x*x+3*x+2));}return n;}
function buildingCost(id){const d=BUILDINGS[id],count=(state.buildings[id]||0)+state.constructionQueue.filter(x=>x.id===id).length+(state.construction?.id===id?1:0);const f=((count+1)**1.25/1000+1)*(count+1);return Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,Math.ceil(v*f)]));}
function canAfford(c){return Object.entries(c).every(([k,v])=>(state.resources[k]||0)>=v);}function pay(c){Object.entries(c).forEach(([k,v])=>state.resources[k]-=v);}
function shipUnlocked(id){const d=SHIPS[id];if(!d)return false;const hull={Fighter:1,Corvette:1,Frigate:2,Destroyer:2,Cruiser:3,Battleship:3}[d.class]||1;return (state.research.fighter||0)>=hull&&(!d.pod||(state.research.cargo||0)>=1);}
function shipCostValue(id){const c=SHIPS[id]?.cost||{};return (c.metal||0)+(c.crystal||0)+(c.eonium||0);}
function playerValue(){const shipVal=Object.values(state.fleets).reduce((sum,f)=>sum+Object.entries(f).reduce((z,[id,count])=>z+shipCostValue(id)*count,0),0)+state.missions.reduce((sum,m)=>sum+Object.entries(m.ships).reduce((z,[id,count])=>z+shipCostValue(id)*count,0),0);const resVal=Object.values(state.resources).reduce((a,b)=>a+b,0)/150;const buildings=Object.values(state.buildings).reduce((a,b)=>a+b,0);return Math.round((shipVal+(state.shipSales||[]).reduce((a,o)=>a+shipCostValue(o.ship)*o.qty,0))/100+resVal+buildings*200+totalRoids(state.roids)*200);}
function playerScore(){return playerValue()+state.xp;}
function npcValue(p){if(p.directoryReadOnly&&Number.isFinite(p.publicValue))return p.publicValue;const fleetVal=Object.entries(p.ships||{}).reduce((z,[id,count])=>z+(SHIPS[id]?.cost.metal+SHIPS[id]?.cost.crystal+SHIPS[id]?.cost.eonium||0)*count/100,0);return Math.round(fleetVal+Object.values(p.resources||{}).reduce((a,b)=>a+b,0)/150+(p.structures||0)*200+totalRoids(p.roids)*200);}
function planetScore(p){if(p.directoryReadOnly&&Number.isFinite(p.publicScore))return p.publicScore;return p.player?playerScore():npcValue(p)+(p.xp||0);}
function resourceHTML(){const inc=income();return Object.entries(RES).map(([id,r])=>`<div class="res"><div class="res-head"><span>${r.label}</span><span class="res-icon">${r.icon}</span></div><div class="res-val">${nfmt(state.resources[id])}</div><div class="res-rate">${signed(inc[id])} / TICK</div></div>`).join('');}
function activeOrderHTML(){const parts=[];if(state.construction)parts.push(`<div class="summary-line"><div><b>${BUILDINGS[state.construction.id].name}</b><small>CONSTRUCTION · ${Math.max(1,Math.ceil(state.construction.remaining/constructionRate()))} TICKS</small></div><span class="tag">${Math.round(100-state.construction.remaining/state.construction.total*100)}%</span></div>`);if(state.researchActive)parts.push(`<div class="summary-line"><div><b>${TECH_TREE.find(t=>t.id===state.researchActive)?.levels[(state.research[state.researchActive]||0)]||TECHS[state.researchActive].name}</b><small>RESEARCH · ${(state.researchProgress[state.researchActive]||0)} / ${researchCost(state.researchActive,(state.research[state.researchActive]||0)+1)}</small></div><span class="tag blue">${Math.floor((state.researchProgress[state.researchActive]||0)/researchCost(state.researchActive,(state.research[state.researchActive]||0)+1)*100)}%</span></div>`);if(state.production)parts.push(`<div class="summary-line"><div><b>${esc(productionOrderLabel(state.production))}</b><small>SHIP ORDER · ${productionTimeText(state.production)}</small></div><span class="tag gold">BUILDING</span></div>`);if(!parts.length)parts.push('<div class="empty">No active projects. Start construction, research, or production.</div>');return parts.join('');}
