function questValue(metric){if(metric==='tick')return state.tick||1;if(metric==='guards')return covertState().guards||0;if(metric==='resourcesTotal')return Object.values(state.resources).reduce((a,b)=>a+b,0);if(metric==='mailSent')return state.mailQuestCount||0;if(metric==='population')return state.population||0;if(metric==='covert:strike')return covertState().strikes||0;if(metric==='covert:biodome')return covertState().biodomeSabotages||0;if(metric==='workforceCapacity')return workforceAllocationLimit();if(metric==='forum:galaxy')return state.forumQuestCounts?.galaxy||0;if(metric==='forum:alliance')return state.forumQuestCounts?.alliance||0;if(metric.startsWith('ticker:'))return state.tickerQuestFlags?.[metric.split(':')[1]]?1:0;if(metric==='agents')return covertState().agents;if(metric==='covertMissions')return covertState().history.length;if(metric==='alert')return Math.floor(covertAlert(state.galaxy.find(p=>p.player)));if(metric.startsWith('setting:'))return state.userSettings[metric.split(':')[1]]?1:0;if(metric==='government')return currentGovernmentName()!=='None'?1:0;if(metric==='workforce')return Object.values(state.workforce||{}).reduce((a,b)=>a+b,0);if(metric.startsWith('workforce:'))return state.workforce[metric.split(':')[1]]||0;if(metric.startsWith('roid:'))return state.roids[metric.split(':')[1]]||0;if(metric==='roids')return totalRoids(state.roids);if(metric==='buildings')return Object.values(state.buildings).reduce((a,b)=>a+b,0);if(metric.startsWith('building:'))return state.buildings[metric.split(':')[1]]||0;if(metric.startsWith('research:'))return state.research[metric.split(':')[1]]||0;if(metric.startsWith('ship:'))return shipTotal(metric.split(':')[1]);if(metric==='xp')return state.xp||0;if(metric==='scans')return state.waves.scans.length;if(metric.startsWith('scanType:')){const code=metric.split(':')[1],types={P:['landing'],D:['development'],U:['unit','advanced'],N:['news','incoming'],J:['jumpgate'],A:['advanced']};return state.waves.scans.filter(x=>(types[code]||[]).includes(x.type)).length;}if(metric.startsWith('mission:'))return state.missions.filter(x=>(x.mission||x.type)===metric.split(':')[1]).length+(state.missionHistory||[]).filter(x=>x.type===metric.split(':')[1]).length;if(metric==='alliance')return state.galaxy.find(p=>p.player)?.alliance&&state.galaxy.find(p=>p.player).alliance!=='Unaffiliated'?1:0;if(metric==='shipvalue')return Object.entries(SHIPS).reduce((a,[id,d])=>a+shipTotal(id)*(d.cost.metal+d.cost.crystal+d.cost.eonium),0);return 0;}
