function renderGalaxyFund(){ensureGalaxyPolitics();const el=document.getElementById('galaxyFundContent');if(!el)return;const bankModule=el.querySelector?.("#spacingBankModule"),bankFocus=document.activeElement&&bankModule?.contains(document.activeElement)?document.activeElement:null,bankSelection=bankFocus&&typeof bankFocus.selectionStart==="number"?[bankFocus.selectionStart,bankFocus.selectionEnd]:null;if(bankModule)bankModule.remove();const fund=state.galaxyFund,metrics=galaxyFundMetrics(),minister=state.politics.ministers.economics||'',canPay=minister===currentPoliticsRuler();el.innerHTML='<section class="panel spaceport-fund-module" aria-labelledby="spaceportFundHeading"><div class="ph"><div class="pt" id="spaceportFundHeading">GALAXY FUND</div><span class="meta">SPACEPORT TREASURY</span></div>'+galaxyTreasuryBriefingHTML()+`<div class="alliance-kpis">${Object.entries(RES).map(([id,r])=>`<div class="alliance-kpi"><small>${r.icon} ${r.label} RESERVE</small><b>${nfmt(fund[id]||0)}</b></div>`).join('')}<div class="alliance-kpi"><small>ELIGIBLE PLANETS</small><b>${metrics.eligible.length}</b></div></div><div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">CONTRIBUTE TO THE FUND</div><span class="meta">OPEN TO ALL PLAYERS</span></div><p class="fund-copy">Any planet can donate resources into the shared Galaxy Fund. Donations are deducted from your available planetary stock immediately.</p><div class="controls"><div class="field"><label for="gfundDepositResource">Resource</label><select id="gfundDepositResource">${Object.entries(RES).map(([id,r])=>`<option value="${id}">${r.label} · available ${nfmt(state.resources[id]||0)}</option>`).join('')}</select></div><div class="field"><label for="gfundDepositAmount">Amount</label><input id="gfundDepositAmount" type="number" min="1" step="1" value="500"></div><button class="btn primary" data-gfund="deposit">DEPOSIT RESOURCES</button></div></section><section class="panel"><div class="ph"><div class="pt">DISTRIBUTE GALAXY AID</div><span class="meta">ECONOMICS MINISTER ONLY</span></div><div class="fund-copy">Strongest planet: <b>${metrics.strongest?esc(metrics.strongest.name):'None'} · ${nfmt(metrics.strongestScore)}</b><br>Eligibility: planet score strictly below <b>${nfmt(metrics.threshold)}</b> (50% of strongest score). Checked again when aid is sent.</div>${canPay?`<div class="controls"><div class="field"><label for="gfundTarget">Recipient planet</label><select id="gfundTarget">${metrics.eligible.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.ruler)} · score ${nfmt(planetScore(p))}</option>`).join('')}</select></div><div class="field"><label for="gfundPayoutResource">Resource</label><select id="gfundPayoutResource">${Object.entries(RES).map(([id,r])=>`<option value="${id}">${r.label} · reserve ${nfmt(fund[id]||0)}</option>`).join('')}</select></div><div class="field"><label for="gfundPayoutAmount">Amount</label><input id="gfundPayoutAmount" type="number" min="1" step="1" value="500"></div><button class="btn primary" data-gfund="payout" ${metrics.eligible.length?'':'disabled'}>SEND AID</button></div>${metrics.eligible.length?'':'<div class="empty">No planets currently meet the score requirement.</div>'}`:`<div class="fund-copy"><span class="tag red">PAYOUTS LOCKED</span><p>Current Economics Minister: <b>${esc(minister||'Unassigned')}</b>. Only the appointed minister can distribute reserves. Assign the Economics Minister in Politics.</p></div>`}</section></div><section class="panel"><div class="ph"><div class="pt">FUND TRANSACTION LOG</div><span class="meta">NEWEST FIRST</span></div><div class="summary-list">${fund.log.length?fund.log.slice(0,30).map(x=>`<div class="summary-line"><span>${esc(x.text)}</span><small>T${String(x.tick).padStart(3,'0')}</small></div>`).join(''):'<div class="empty">No Galaxy Fund transactions recorded.</div>'}</div></section><div class="note" style="margin-top:12px">The payout limit is recalculated from current planet scores for every transaction. Planets at exactly half the strongest score are not eligible.</div></section>`;if(bankModule){el.append(bankModule);if(bankFocus){bankFocus.focus?.({preventScroll:true});if(bankSelection)bankFocus.setSelectionRange?.(...bankSelection);}}if(typeof ensureSpacingBankMounted==='function')ensureSpacingBankMounted();}
