document.addEventListener('click',e=>{const tab=e.target.closest('[data-atab]');if(tab){allianceTab=tab.dataset.atab;renderAlliance();}const act=e.target.closest('[data-alliance]');if(act){if(act.dataset.alliance==='respond')respondDefence();else allianceAction(act.dataset.alliance,act);}const open=e.target.closest('[data-openbcalc]');if(open){const c=state.alliance.calls.find(x=>x.id===open.dataset.openbcalc);if(c)window.bcalcResult=`<b>DEFENCE CALL</b><br>${esc(c.planet)} · ETA ${c.eta}<br>${esc(c.notes)}<br>Threat fleet count: ${c.attackerCount}`;allianceTab='bcalc';renderAlliance();}const parse=e.target.closest('[data-parse]');if(parse){const side=parse.dataset.parse,text=document.getElementById(side==='a'?'parseA':'parseD').value,counts=parseShipReport(text);window.bcalc=window.bcalc||{a:{},d:{}};window.bcalc[side]=counts;renderAlliance();notify('Ship counts parsed into the calculator.');}const calc=e.target.closest('[data-calculate]');if(calc)calculateBattle();const copybtn=e.target.closest('[data-copycalc]');if(copybtn)copyText(bcalcCopy(copybtn.dataset.copycalc));if(e.target.closest('[data-universe-clear]')){state.universeSearch='';state.universeFilter='all';renderUniverse();}const admTab=e.target.closest('[data-admin-tab]');if(admTab){adminTab=admTab.dataset.adminTab;renderAdmin();}const claim=e.target.closest('[data-claimquest]');if(claim)claimQuest(claim.dataset.claimquest);const adm=e.target.closest('[data-admin]');if(adm)adminAction(adm.dataset.admin);const politics=e.target.closest('[data-politics]');if(politics)politicsAction(politics.dataset.politics);const gfund=e.target.closest('[data-gfund]');if(gfund)galaxyFundAction(gfund.dataset.gfund);const approve=e.target.closest('[data-approveexile]');if(approve)approveExile(approve.dataset.approveexile);const scan=e.target.closest('[data-scan]');if(scan)runScan(scan.dataset.scan);if(e.target.closest('[data-galaxyscan]'))runGalaxyScan();const cp=e.target.closest('[data-copyscan]');if(cp){const sc=state.waves.scans.find(x=>x.id===cp.dataset.copyscan);if(sc)copyText(`${sc.name} · ${sc.targetName}${sc.anonymous?'':' · '+sc.coords}\\n${sc.text}`);}const toggle=e.target.closest('[data-coords]');if(toggle){const sc=state.waves.scans.find(x=>x.id===toggle.dataset.coords);if(sc){sc.anonymous=!sc.anonymous;update();}}const del=e.target.closest('[data-deletescan]');if(del){state.waves.scans=state.waves.scans.filter(x=>x.id!==del.dataset.deletescan);update();}if(e.target.closest('[data-politics]')){} });
document.addEventListener('input',e=>{if(e.target.id==='universeSearch'){state.universeSearch=e.target.value;renderUniverse();}if(e.target.id==='newsSearch'){state.newsSearch=e.target.value;renderNews();save();}if(e.target.matches('[data-shipqty]')){state.shipOrderAmounts=state.shipOrderAmounts||{};state.shipOrderAmounts[e.target.dataset.shipqty]=e.target.value;save();updateShipPreview(e.target.dataset.shipqty);}if(e.target.id==='anonymousScan'){state.waves.anonymous=e.target.checked;save();}if(e.target.matches('[data-wave-coord]')){state.waves.targetCoords[e.target.dataset.waveCoord]=e.target.value;save();}if(e.target.matches('[data-cship]')){window.bcalc=window.bcalc||{a:{},d:{}};window.bcalc[e.target.dataset.cship][e.target.dataset.ship]=Number(e.target.value)||0;}});
document.addEventListener('click',e=>{const summary=e.target.closest('#nav .nav-group>summary');if(summary&&state.userSettings?.keepMenuUnfolded){e.preventDefault();document.querySelectorAll('#nav .nav-group').forEach(x=>x.open=true);}},true);
document.addEventListener('click',e=>{const assign=e.target.closest('[data-factory-assign-all]');if(!assign)return;state.factoryAssignments=state.factoryAssignments||{};for(const id of Object.keys(FACTORY_WEIGHTS))state.factoryAssignments[id]=factoryOwned(id);update();notify('All available factories are assigned to production.');});
document.addEventListener('change',e=>{if(e.target.matches('[data-factoryassign]')){const id=e.target.dataset.factoryassign,owned=factoryOwned(id),requested=Math.floor(Number(e.target.value)||0);state.factoryAssignments[id]=Math.max(0,Math.min(owned,requested));update();notify(`${state.factoryAssignments[id]} ${FACTORY_LABELS[id][0]} assigned to production.`);return;}if(e.target.id==='keepMenuUnfolded'){state.userSettings.keepMenuUnfolded=e.target.checked;localStorage.setItem('starfall-menu-unfolded',e.target.checked?'1':'0');applyMenuPreference();save();notify(e.target.checked?'All sidebar sections will stay open.':'Sidebar returned to accordion mode.');}if(e.target.id==='planetRaceSelect'){setPlanetRace(e.target.value);}if(e.target.id==='allianceTaxEnabled'){state.userSettings.allianceTaxEnabled=e.target.checked;save();update();notify(e.target.checked?'Alliance tax enabled for your planet.':'Alliance tax disabled for your planet.');}if(e.target.id==='allianceScansEnabled'){state.userSettings.allianceScansEnabled=e.target.checked;save();renderPlanetSettings();renderWaves();notify(e.target.checked?'Alliance scan sharing enabled.':'Alliance scan sharing disabled.');}if(e.target.id==='skinRaceSelect'){state.userSettings.skinRace=e.target.value;applyRaceSkin();save();renderPlanetSettings();renderQuests();notify(`Interface theme changed to ${themeLabel(e.target.value)}.`);location.hash='planetSettings';location.reload();}if(e.target.id==='admShipRaceFilter'){state.adminShipRaceFilter=e.target.value;renderAdmin();}if(e.target.id==='universeFilter'){state.universeFilter=e.target.value;renderUniverse();}if(e.target.id==='newsAllCategories'){state.newsCategories=Object.fromEntries(NEWS_CATEGORIES.map(x=>[x,e.target.checked]));renderNews();save();}if(e.target.matches('[data-news-category]')){state.newsCategories[e.target.dataset.newsCategory]=e.target.checked;renderNews();save();}if(e.target.matches('[data-trust]')){ensureGalaxyPolitics();if(politicsPlanets().some(p=>p.id===e.target.dataset.trust))state.politics.trust[e.target.dataset.trust]=e.target.value;}if(e.target.matches('[data-fundallow]'))state.politics.allowedFund[e.target.dataset.fundallow]=e.target.checked;if(e.target.matches('[data-scan-funding]')){if(!isCurrentScanner())return notify('Only the Alliance HC or an appointed scanner can change scan funding.',true);state.waves.fundSources=state.waves.fundSources||{};state.waves.fundSources['A. Commander']=e.target.dataset.scanFunding;update();notify(`Scan funding switched to ${scanFundLabel(e.target.dataset.scanFunding)}.`);}if(e.target.matches('[data-member-role]'))updateAllianceMemberRank(e.target.dataset.memberRole,e.target.value);});
// Galaxy coordinates retain the existing X:Y representation; planet slots are 1–10.
function galaxyOf(coords){return String(coords||'').split(':').slice(0,2).map(n=>padCoord(Number(n))).join(':');}
function homeGalaxy(){return galaxyOf((state.galaxy.find(p=>p.player)||state.galaxy[0]).coords);}
function memberCoordinates(name){if(name==='A. Commander'){const home=state.galaxy.find(p=>p.player);if(home&&isAllianceMember(name))return home.coords;}const member=state.alliance.members.find(m=>m.name===name);if(!member)return '';const p=state.galaxy.find(p=>p.ruler===name||p.name===member.planet);return p?.coords||member.coords||'';}
function isStrongholdResident(name){if(state.centralPlayerId&&state.alliance.fortress.claimStatus!=='active')return false;return isAllianceMember(name)&&!!state.alliance.fortress.strongholdGalaxy&&galaxyOf(memberCoordinates(name))===state.alliance.fortress.strongholdGalaxy;}
function galaxyHTML(){const key=homeGalaxy(),planets=state.galaxy.filter(p=>galaxyOf(p.coords)===key),rows=galaxyPlanetHTML().match(/<tr>[\s\S]*?<\/tr>/g)||[],bySlot=new Map(planets.map((p,i)=>[Number(p.coords.split(':')[2]),rows[i]]));return Array.from({length:10},(_,i)=>bySlot.get(i+1)||'<tr data-slot="'+(i+1)+'"><td><b>Empty</b><small>'+key+':'+padCoord(i+1)+'</small></td><td>—</td><td colspan="5">Planet slot</td><td>—</td><td>—</td></tr>').join('')+galaxyExtraRows(key,6);}
function updateHomeWorldSurvey(){const type=planetTypeFor(state),art=document.getElementById('homePlanetTypeArtwork'),src='/assets/planets/'+type.id+'.svg';if(art?.getAttribute&&art.getAttribute('src')!==src){art.src=src;art.alt=type.name+' orbital survey';}for(const [id,value] of [['homeWorldType',type.name],['homeWorldHabitability',type.habitability+'%'],['homeWorldGrowth',(type.growthPercent>=0?'+':'')+type.growthPercent+'%'],['homeWorldBase',nfmt(type.basePopulation)]]){const e=document.getElementById(id);if(e&&e.textContent!==value)e.textContent=value;}}
function updateHomeCoordinates(){updateHomeWorldSurvey();const home=state.galaxy.find(p=>p.player);if(!home)return;for(const [id,value] of [['headerPlanetName',displayPlanetName(home.name)||'Home Planet'],['homeSceneName',displayPlanetName(home.name)||'Home Planet'],['homeSceneRace','COMMAND PLANET · '+(state.race||home.race||'Terran').toUpperCase()],['homeHeroTitle',(displayPlanetName(home.name)||'Home Planet')+', under your command.'],['homeHeroDescription','Ruler: '+(home.ruler||'Unassigned')+(home.username?' · Commander: '+home.username:'')+' · '+home.coords],['headerPlanetCoords',home.coords],['headerPlanetRuler',home.ruler||'Unassigned'],['headerAccountId',state.accountId||'—'],['headerPlanetTick',String(state.tick).padStart(3,'0')],['headerPlanetScore',nfmt(playerScore())],['headerPlanetXP',nfmt(state.xp)],['headerPlanetValue',nfmt(playerValue())],['homeGalaxyLabel','Planetary command · Galaxy '+homeGalaxy()],['homeSceneCoordinates',home.coords.split(':').join(' : ')],['homeRailCoordinates','REALTIME · PLANET '+home.coords],['homeGalaxyStatusLabel','Galaxy '+homeGalaxy()+' · local practice round']]){const el=document.getElementById(id);if(el)el.textContent=value;}}
function freePlanetCoordinates(excludedGalaxy=''){
  const occupied=new Set(state.galaxy.map(p=>p.coords));
  const [sector]=homeGalaxy().split(':').map(Number);
  for(let offset=1;offset<=100;offset++){
    const y=((Number(homeGalaxy().split(':')[1])-1+offset)%100)+1,key=`${padCoord(sector)}:${padCoord(y)}`;
    if(key===excludedGalaxy)continue;
    for(let z=1;z<=10;z++){const coords=`${key}:${padCoord(z)}`;if(!occupied.has(coords))return coords;}
  }
  return null;
}
function movePlanet(p,coords){const old=p.coords;p.coords=coords;p.exiled=false;for(const m of state.alliance.members)if(m.name===p.ruler||m.planet===p.name)m.coords=coords;for(const a of state.alliance.applicants)if(a.name===p.ruler||a.planet===p.name)a.coords=coords;return old;}
function normalizeGalaxySlots(){
  const occupied=new Set();
  for(const p of state.galaxy){if(p.ghostPlanet===true)continue;const z=Number(String(p.coords).split(':')[2]);if(z<1||z>10||occupied.has(p.coords)){const coords=freePlanetCoordinates();if(coords)movePlanet(p,coords);}occupied.add(p.coords);}
  for(const p of state.structurePlanets){if(Number(p.slot)===10){const used=new Set(state.structurePlanets.filter(q=>q!==p&&galaxyOf(q.coords)===galaxyOf(p.coords)).map(q=>Number(q.slot)));const slot=currentGalaxySlotLayout(galaxyOf(p.coords)).structureSlots.find(n=>!used.has(n));if(slot){p.slot=slot;p.coords=galaxyOf(p.coords)+':'+padCoord(slot);const effect=state.alliance.structures.active.find(a=>a.id===p.id);if(effect)effect.slot=slot;}}}
}
function calculateSelfExileCost(value,count,galaxyScore,averageScore,free=false){const base=Math.max(0,value)/10,ratio=Math.max(0,galaxyScore)/Math.max(1,Math.trunc(averageScore));const cost=base+Math.trunc(2*(base+1000)*Math.pow(Math.max(0,count)+1,2.5)*Math.pow(ratio,2.5));return Math.ceil(cost*(free?2:1));}
function selfExileCost(forceFree){const scores=new Map();for(const p of state.galaxy){const key=galaxyOf(p.coords);if(key==='01:01'||Number(key.split(':')[0])===200)continue;const counted=Math.max(0,planetScore(p)-(Number(p.galaxyEntryScore)||0));scores.set(key,(scores.get(key)||0)+counted);}const avg=scores.size?[...scores.values()].reduce((a,b)=>a+b,0)/scores.size:1;const current=state.galaxy.filter(p=>galaxyOf(p.coords)===homeGalaxy()).reduce((a,p)=>a+Math.max(0,planetScore(p)-(Number(p.galaxyEntryScore)||0)),0);return calculateSelfExileCost(playerValue(),state.selfExileCount||0,current,avg,forceFree===undefined?state.accountType==='free':forceFree);}
function requestSelfExile(checkbox){
  if(!checkbox.checked)return;
  checkbox.checked=false;
  const home=state.galaxy.find(p=>p.player);if(!home)return;
  const cost=selfExileCost();if(!Number.isSafeInteger(cost)||!Object.keys(RES).every(k=>state.resources[k]>=cost))return notify('Not enough resources for self exile: '+nfmt(cost)+' Metal, Crystal and Eonium required.',true);if(state.missions.length)return notify('All fleets must be at home before self exile.',true);if(!confirm('Exile to a different galaxy for '+nfmt(cost)+' Metal + '+nfmt(cost)+' Crystal + '+nfmt(cost)+' Eonium? Payment goes to the galaxy you are leaving. Fleets, buildings, research and alliance membership are preserved.'))return;
  const oldGalaxy=galaxyOf(home.coords),coords=freePlanetCoordinates(oldGalaxy);
  if(!coords)return notify('No free planet slot is available in another galaxy.',true);
  state.galaxyFunds=state.galaxyFunds||{};const originFund=copy(state.galaxyFund);for(const k of Object.keys(RES)){state.resources[k]-=cost;originFund[k]=(originFund[k]||0)+cost;}state.galaxyFunds[oldGalaxy]=originFund;state.selfExileCount=(state.selfExileCount||0)+1;const old=movePlanet(home,coords);home.galaxyEntryScore=planetScore(home);
  const [x,y]=coords.split(':').map(Number);state.browserCoords={x,y};
  state.politics={...freshState().politics,gc:home.ruler,votes:{[home.ruler]:1},ministers:{},exiles:[],votesToExile:[]};
  state.galaxyFund=copy(state.galaxyFunds[galaxyOf(coords)]||{metal:0,crystal:0,eonium:0,log:[]});
  addNews(`Your planet moved from ${old} to ${coords} by Exile Option.`,'warn');update();
}
function renderGalaxyBrowser(){
  renderGalaxyPlanets();
  const rows=document.getElementById('browserPlanetRows');if(!rows)return;
  const data=browserGalaxyData(),key=`${padCoord(state.browserCoords.x)}:${padCoord(state.browserCoords.y)}`;
  const planetRows=rows.innerHTML.match(/<tr>[\s\S]*?<\/tr>/g)||[];
  const bySlot=new Map(data.planets.map((p,i)=>[Number(p.coords.split(':')[2]),planetRows[i]]));
  const map=document.getElementById('browserPlanetMap');const chips=map.innerHTML.match(/<div class="planet-chip[\s\S]*?<\/div>/g)||[];
  const chipsBySlot=new Map(data.planets.map((p,i)=>[Number(p.coords.split(':')[2]),chips[i]]));
  const rowSlots=[],mapSlots=[];
  for(const entry of currentGalaxySlotLayout(key).slots){const slot=entry.slot;
    const structure=entry.kind==='structure'?state.structurePlanets.find(p=>galaxyOf(p.coords)===key&&Number(p.slot)===slot):entry.kind==='ghost'?(state.ghostPlanets||[]).find(p=>galaxyOf(p.coords)===key&&Number(String(p.coords).split(':')[2])===slot):null;
    if(slot<=10&&bySlot.has(slot)){rowSlots.push(bySlot.get(slot));mapSlots.push(chipsBySlot.get(slot));continue;}
    const label=structure?structure.name:entry.kind==='ghost'?'Ghost / Reserved':slot<=10?'Empty':'Empty / Reserved';
    rowSlots.push(`<tr class="${structure?'structure-slot-row':'reserved-slot'}" data-slot="${slot}"><td>${padCoord(slot)}</td><td>${structure?esc(structure.ruler||structure.alliance):'—'}</td><td>${structure?'<em>'+esc(label)+'</em>':esc(label)}<small>${key}:${padCoord(slot)}</small></td><td>—</td><td>${structure?esc(structure.alliance):'—'}</td><td colspan="3">${entry.kind==='ghost'?'Ghost planet · no player account':slot<=10?'Planet slot':'Alliance stronghold structure'}</td><td>—</td><td>—</td></tr>`);
    mapSlots.push(`<div class="planet-chip ${structure?'ally':'reserved-slot'}"><i class="planet-dot"></i><span>${padCoord(slot)} · ${esc(label)}</span></div>`);
  }
  rows.innerHTML=rowSlots.join('');map.innerHTML=mapSlots.join('');renderGalaxyIntelOverlay();
  document.getElementById('browserPlanetCount').textContent=`${data.planets.length} PLANETS · ${currentGalaxySlotLayout(key).slots.length} SLOTS · REGISTERED`;
}
function parseCustomScanCoordinates(text){
  const raw=String(text||'').trim();const full=raw.match(/^(\d{1,3})\s*:\s*(\d{1,3})\s*:\s*(\d{1,2})$/),compact=raw.match(/^(\d{1,3})\s*:\s*(\d{1,2})$/);
  const values=full?full.slice(1).map(Number):compact?[Number(homeGalaxy().split(':')[0]),...compact.slice(1).map(Number)]:null;
  if(!values||values[0]<1||values[0]>100||values[1]<1||values[1]>100||values[2]<1||!(typeof validGalaxyScanSlot==='function'?validGalaxyScanSlot(values.slice(0,2).join(':'),values[2],[...(state.allianceDirectory||[]),state.alliance],state.structurePlanets||[],state.ghostPlanets||[]):values[2]<=15))return null;
  return Object.fromEntries(['x','y','z'].map((k,i)=>[k,padCoord(values[i])]));
}
function applyCustomScanCoordinates(source){
  const input=document.getElementById(source==='paste'?'pasteScanCoordinates':'customScanCoordinates'),coords=parseCustomScanCoordinates(input.value);
  const feedback=document.getElementById('scanCoordinateFeedback');
  if(!coords){feedback.textContent='Invalid coordinates. Enter Galaxy:slot (2:7) or X:Y:Z (07:04:01), with slot 1–15.';return;}
  state.waves.targetCoords=coords;save();renderWaves();document.getElementById('scanCoordinateFeedback').textContent=`Scan target set to ${coords.x}:${coords.y}:${coords.z}. Select a scan below to launch it.`;
}
