function createAllianceLocal(){const name=(document.getElementById('newAllianceName')?.value||'').trim(),tag=(document.getElementById('newAllianceTag')?.value||'').trim().toUpperCase();if(name.length<3||name.length>40)return notify('Use an alliance name of 3–40 characters.',true);if(!/^[A-Z0-9]{2,8}$/.test(tag))return notify('Use a tag of 2–8 letters or numbers.',true);if(allianceChoices().some(n=>n.toLowerCase()===name.toLowerCase()))return notify('An alliance with that name already exists.',true);const home=state.galaxy.find(p=>p.player);if(!home)return;state.allianceDirectory=state.allianceDirectory||[];const old=copy(state.alliance);if(!state.allianceDirectory.some(a=>a.name===old.name))state.allianceDirectory.push(old);const fresh=copy(freshState().alliance);fresh.name=name;fresh.tag=tag;fresh.description=document.getElementById('newAllianceDescription')?.value||'';fresh.recruitmentMessage=document.getElementById('newAllianceRecruitment')?.value||'';fresh.motd=document.getElementById('newAllianceMotd')?.value||'';fresh.fund={metal:0,crystal:0,eonium:0};fresh.members=[{id:'member-'+home.id,planetId:home.id,name:home.username||home.ruler,planet:home.name,coords:home.coords,rank:'Owner',online:true}];fresh.applicants=[];fresh.message='Welcome to '+name+'.';state.alliance=fresh;home.alliance=name;let created=0;for(let i=0;!state.centralPlayerOnly&&i<5&&state.galaxy.length<40;i++){const coords=freePlanetCoordinates();if(!coords)break;state.dummyPlanetCount=(state.dummyPlanetCount||0)+1;const n=state.dummyPlanetCount;state.galaxy.push({id:'dummy-'+Date.now()+'-'+n,name:'Practice Planet '+n,ruler:'Practice Commander '+n,race:'Terran',alliance:'Unaffiliated',coords,roids:{metal:6,crystal:6,eonium:6},resources:{metal:9000,crystal:9000,eonium:9000},ships:normalizeFleet({}),xp:0,structures:0,dummy:true});created++;}state.allianceCreated=true;if(document.getElementById('allianceCreatePanel'))document.getElementById('allianceCreatePanel').open=false;allianceTab='home';addNews('Alliance '+name+' ['+tag+'] created. '+created+' unassigned practice planets are available for Administration.','good');update();navigate('alliance');notify('Alliance created. Assign practice planets from Administration → Planets.');}
function allianceProfile(name){if(name===state.alliance.name)return state.alliance;state.allianceDirectory=state.allianceDirectory||[];let a=state.allianceDirectory.find(a=>a.name===name);if(!a&&name&&name!=='Unaffiliated'){a={...copy(freshState().alliance),name,members:[],applicants:[],fund:{metal:0,crystal:0,eonium:0},wars:[]};state.allianceDirectory.push(a);}return a;}
function syncEditedAllianceMember(p,previous=p){for(const a of [state.alliance,...(state.allianceDirectory||[])])a.members=(a.members||[]).filter(m=>!((m.planetId===p.id||m.planet===previous.name||m.planet===p.name)&&a.name!==p.alliance));const a=allianceProfile(p.alliance);if(!a)return;let m=(a.members||[]).find(m=>m.planetId===p.id||m.planet===previous.name||m.planet===p.name);if(!m){m={id:'member-'+p.id,name:p.player?'A. Commander':p.ruler,rank:p.player?'HC':'Member',online:!!p.player};a.members.push(m);}m.planetId=p.id;m.planet=p.name;m.coords=p.coords;if(!p.player)m.name=p.username||p.ruler;}
function reconcileAllianceMembers(){for(const a of [state.alliance,...(state.allianceDirectory||[])]){a.members=(a.members||[]).filter(m=>{const p=state.galaxy.find(p=>m.planetId===p.id||m.planet===p.name);return !p||p.alliance===a.name;});for(const m of a.members){const p=state.galaxy.find(p=>m.planetId===p.id||m.planet===p.name);if(p){m.planetId=p.id;m.planet=p.name;m.coords=p.coords;}}}for(const p of state.galaxy){const a=allianceProfile(p.alliance);if(a&&!(a.members||[]).some(m=>m.planetId===p.id||m.planet===p.name))syncEditedAllianceMember(p);}}

