function addAdminDummyMember(allianceName){
 const name=allianceName||document.getElementById('admDummyAlliance')?.value;
 if(!name||name==='Unaffiliated'||!allianceChoices().includes(name))return notify('Choose an alliance for the dummy member.',true);
 const alliance=name===state.alliance.name?state.alliance:(state.allianceDirectory||[]).find(a=>a.name===name);
 if(state.galaxy.length>=40)return notify('Planet capacity reached (40).',true);
 if((alliance?.members?.length||state.galaxy.filter(p=>p.alliance===name).length)>=40)return notify('Alliance member capacity reached (40).',true);
 const coords=freePlanetCoordinates();if(!coords)return notify('No free planet slot is available.',true);
 state.dummyPlanetCount=(state.dummyPlanetCount||0)+1;const n=state.dummyPlanetCount;
 const p={id:'dummy-'+Date.now()+'-'+n,name:'Practice Planet '+n,ruler:'Practice Commander '+n,race:'Terran',alliance:name,coords,roids:{metal:6,crystal:6,eonium:6},resources:{metal:9000,crystal:9000,eonium:9000},ships:normalizeFleet({}),xp:0,structures:0,dummy:true};
 state.galaxy.push(p);if(alliance){alliance.members=alliance.members||[];alliance.members.push({id:'member-'+p.id,name:p.ruler,planet:p.name,coords,rank:'Member',online:false});}
 state.adminSelected=p.id;const [x,y]=coords.split(':').map(Number);state.adminBrowserCoords={x,y};
 addNews('Administrator added '+p.ruler+' to '+name+'.','good');update();if(typeof syncPlanetDirectory==='function')syncPlanetDirectory();notify('Dummy member added to '+name+'.');
}
