function allianceIntelDetailHTML(){const a=state.alliance,coords=a.intelTarget;if(!coords)return '<div class="empty">Select a planet to view scan intelligence and record an assessment.</div>';const record=a.intelRecords?.[coords]||{},editable=mayAlliance('intelNotes'),viewNotes=mayIntelField('notes'),viewAssessment=mayIntelField('assessment');return '<div class="ph"><div class="pt">INTEL DOSSIER · '+coords+'</div><span class="meta">'+(editable?'EDITABLE':'VIEW ONLY')+'</span></div><div class="controls"><div class="field"><label for="intelThreat">Assessment</label><select id="intelThreat" '+(editable&&viewAssessment?'':'disabled')+'>'+['Unassessed','Friendly','Watch','Hostile'].map(status=>'<option '+(status===(viewAssessment?(record.status||'Unassessed'):'Unassessed')?'selected':'')+'>'+status+'</option>').join('')+'</select></div><div class="field"><label for="intelNote">Alliance intel notes</label><textarea id="intelNote" maxlength="2000" rows="3" '+(editable&&viewNotes?'':'disabled')+'>'+esc(viewNotes?(record.note||''):'Your rank cannot view intel notes.')+'</textarea></div><button class="btn primary" data-intel-save '+(editable?'':'disabled')+'>SAVE ASSESSMENT</button><button class="btn" data-intel-refresh>REFRESH SCANS</button></div><p class="meta" id="intelScanStatus" style="padding:0 12px">Your saved reports are shown below. Refresh to include central shared reports.</p><div id="intelScanReports">'+intelReportHTML(state.waves.scans.filter(sc=>!sc.anonymous&&sc.coords===coords&&mayIntelField(sc.type)))+'</div>';}
