function browseAllianceIntel(step=0){if(!mayAlliance('intel'))return;let x=Number(document.getElementById('intelSector')?.value),y=Number(document.getElementById('intelGalaxy')?.value);if(!Number.isInteger(x)||!Number.isInteger(y)||x<1||x>100||y<1||y>100)return;y+=step;if(y>100){y=1;x=x===100?1:x+1;}if(y<1){y=100;x=x===1?100:x-1;}state.alliance.intelBrowserCoords={x,y};state.alliance.intelTarget='';save();renderAlliance();}
