document.addEventListener('click',e=>{const target=e.target.closest('[data-intel-target]'),step=e.target.closest('[data-intel-step]');if(target&&mayAlliance('intel')){state.alliance.intelTarget=target.dataset.intelTarget;save();renderAlliance();document.getElementById('allianceIntelDetail')?.scrollIntoView?.({behavior:'smooth',block:'start'});loadAllianceIntelScans();}if(step||e.target.closest('[data-intel-browse]'))browseAllianceIntel(step?Number(step.dataset.intelStep):0);if(e.target.closest('[data-intel-save]'))saveAllianceIntel();if(e.target.closest('[data-intel-refresh]'))loadAllianceIntelScans();if(e.target.closest('[data-intel-search]')){state.alliance.intelSearch=document.getElementById('allianceIntelSearch').value.trim();save();renderAlliance();}});

