function selectedProductionFleet(id){const value=document.getElementById('shipFleet-'+id)?.value||state.shipFleetTargets?.[id]||'base';return ['base','f1','f2','f3','f4'].includes(value)?value:'base';}
function productionOrderItems(o){return Array.isArray(o.items)?o.items:[{id:o.id,qty:o.qty,fleet:o.destinationFleet||'base'}];}
function productionOrderLabel(o){return productionOrderItems(o).map(item=>item.qty+' × '+(SHIPS[item.id]?.name||item.id)+' → '+fleetLabel(item.fleet||'base')).join(' · ');}
function completeProductionOrder(order){for(const item of productionOrderItems(order)){const fleet=['base','f1','f2','f3','f4'].includes(item.fleet)?item.fleet:'base';state.fleets[fleet][item.id]=(state.fleets[fleet][item.id]||0)+item.qty;}addNews(productionOrderLabel(order)+' completed. Ships delivered to the selected fleets.','good');}
function addShipToDraft(id){const ship=SHIPS[id];if(!ship||!shipUnlocked(id)||!state.buildings[ship.factory])return notify('Unlock the ship and build its factory first.',true);const qty=Math.floor(Number(document.getElementById('qty-'+id)?.value)||0);if(qty<1||qty>20000)return notify('Enter 1–20,000 ships.',true);const fleet=selectedProductionFleet(id),draft=state.productionDraft=state.productionDraft||[],entry=draft.find(item=>item.id===id&&item.fleet===fleet);if(entry&&entry.qty+qty>20000)return notify('A draft item can contain at most 20,000 ships.',true);if(entry)entry.qty+=qty;else draft.push({id,qty,fleet});save();renderProductionDraft();notify('Added to draft. Use Order all to confirm.');}
function productionDraftCost(items){const bill={metal:0,crystal:0,eonium:0};for(const item of items.filter(x=>SHIPS[x.id]))for(const [r,n] of Object.entries(shipProductionCost(item.id)))bill[r]+=n*item.qty;return bill;}
function renderProductionDraft(){const el=document.getElementById('productionDraft');if(!el)return;const draft=state.productionDraft||[],cost=draft.length?productionDraftCost(draft):{metal:0,crystal:0,eonium:0};el.innerHTML='<section class="panel"><div class="ph"><div class="pt">DRAFT SHIP ORDER</div><span class="meta">NOT CONFIRMED · NO RESOURCES CHARGED</span></div>'+(draft.length?'<div class="table-wrap"><table class="table"><thead><tr><th>Ship</th><th>Amount</th><th>Destination on completion</th><th></th></tr></thead><tbody>'+draft.map((item,i)=>'<tr><td>'+esc(SHIPS[item.id]?.name||item.id)+'</td><td>'+nfmt(item.qty)+'</td><td>'+esc(fleetLabel(item.fleet))+'</td><td><button class="btn" data-remove-ship-draft="'+i+'">REMOVE</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Use Add to order on ship cards to build a combined order.</div>')+'<div class="controls"><span class="meta">TOTAL · '+constructionCostText(cost)+'</span><button class="btn primary" data-confirm-ship-draft '+(!draft.length?'disabled':'')+'>ORDER ALL</button><button class="btn" data-clear-ship-draft '+(!draft.length?'disabled':'')+'>CLEAR DRAFT</button></div><div class="note" style="margin:12px">Order all confirms this draft as one combined order. Prices include the current government discount and are checked again at confirmation. Each ship is delivered to its selected fleet when the order completes.</div></section>';}
function confirmShipDraft(){const draft=state.productionDraft||[];if(!draft.length)return notify('Add ships to the draft first.',true);if(state.production&&state.productionQueue.length>=1)return notify('One active and one queued ship order are allowed. The draft is preserved.',true);for(const item of draft){const ship=SHIPS[item.id];if(!ship||ship.race!==state.race||!shipUnlocked(item.id)||!state.buildings[ship.factory]||!Number.isSafeInteger(item.qty)||item.qty<1||item.qty>20000||!['base','f1','f2','f3','f4'].includes(item.fleet))return notify('A draft item is no longer valid or unlocked. Review the draft.',true);}const cost=productionDraftCost(draft);if(!canAfford(cost))return notify('Not enough resources to confirm the whole draft. No resources were charged.',true);const items=copy(draft),total=Object.values(cost).reduce((n,v)=>n+v,0),order={id:items[0].id,qty:items.reduce((n,item)=>n+item.qty,0),items,total,remaining:total,cost,orderNumber:state.nextShipOrderNumber=(state.nextShipOrderNumber||0)+1,factoryAssignments:copy(state.factoryAssignments||{})};initializeProductionOrder(order);pay(cost);if(!state.production)state.production=order;else state.productionQueue.push(order);state.productionDraft=[];addNews('Combined ship order #'+order.orderNumber+' confirmed: '+productionOrderLabel(order)+'.','good');update();notify('Order all confirmed.');refreshPageAfterOrder();}
document.addEventListener('change',e=>{if(e.target.dataset.shipDestination){state.shipFleetTargets=state.shipFleetTargets||{};state.shipFleetTargets[e.target.dataset.shipDestination]=e.target.value;save();}});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-ship-draft]'),remove=e.target.closest('[data-remove-ship-draft]');if(add)addShipToDraft(add.dataset.addShipDraft);if(remove){state.productionDraft.splice(Number(remove.dataset.removeShipDraft),1);save();renderProductionDraft();}if(e.target.closest('[data-clear-ship-draft]')){state.productionDraft=[];save();renderProductionDraft();}if(e.target.closest('[data-confirm-ship-draft]'))confirmShipDraft();});

function recordBattleNews(m,target,fight){const report={id:'battle-'+state.tick+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),tick:state.tick,coords:target.coords||'',targetId:target.id,target:target.name,attackerName:m.name||'Attacking fleet',defenderName:target.name,attacker:copy(fight.arrivedA),defender:copy(fight.arrivedD),survivorsA:copy(fight.attacker),survivorsD:copy(fight.defender),habitat:copy(fight.habitat),population:{before:fight.populationBefore,lost:fight.populationLost,after:fight.populationAfter,damagePercent:fight.populationDamagePercent},salvage:{metal:0,crystal:0,eonium:0}};report.earthSalvage=earthBattleSalvage(report,target);if(report.earthSalvage){report.salvage=report.earthSalvage.award;queueEarthSalvage(report);}addNews('Combat: '+report.attackerName+' fighting at '+report.coords+' · '+report.target,'warn');state.news[0].battleReport=report;}
function battleNewsHTML(r){const side=(name,arrived,survived)=>'<h4>Report of losses from '+esc(name)+' fighting at '+esc(displayCoords(r.coords))+'</h4><table class="table"><thead><tr><th>Ship</th><th>Arrived</th><th>Lost</th></tr></thead><tbody>'+Object.entries(arrived||{}).filter(([,n])=>n>0).map(([id,n])=>'<tr data-ship-class="'+esc(SHIPS[id]?.class||'')+'"><td>'+esc(SHIPS[id]?.name||id)+'</td><td>'+nfmt(n)+'</td><td class="loss">'+nfmt(n-(survived?.[id]||0))+'</td></tr>').join('')+'</tbody></table>';return '<section class="battle-news-report">'+side(r.attackerName,r.attacker,r.survivorsA)+side(r.defenderName,r.defender,r.survivorsD)+(r.population?'<h4>Population impact</h4><table class="table"><thead><tr><th>Before</th><th>Pop dmg%</th><th>Casualties</th><th>Survivors</th><th>Mining bonus after</th><th>Population CU / RP after</th></tr></thead><tbody><tr><td>'+nfmt(r.population.before)+'</td><td>'+Number(r.population.damagePercent||0).toLocaleString('en-US',{maximumFractionDigits:3})+'%</td><td class="loss">'+nfmt(r.population.lost)+'</td><td>'+nfmt(r.population.after)+'</td><td>+'+(r.population.after*.001).toFixed(3)+'%</td><td>+'+Math.floor(r.population.after/100)+' CU / RP</td></tr></tbody></table>':'')+(r.habitat?.before?'<h4>Biodome impact</h4><table class="table"><thead><tr><th>Before</th><th>Destroyed</th><th>Remaining</th><th>Surviving dome damage</th><th>Habitat casualties</th></tr></thead><tbody><tr><td>'+nfmt(r.habitat.before)+'</td><td class="loss">'+nfmt(r.habitat.destroyed)+'</td><td>'+nfmt(r.habitat.after)+'</td><td>'+((r.habitat.damageAfter||0)/10).toFixed(1)+'%</td><td>'+nfmt(r.habitat.populationLost)+'</td></tr></tbody></table>':'')+'<h4>Salvage report</h4><table class="table"><thead><tr><th>Metal</th><th>Crystal</th><th>Eonium</th></tr></thead><tbody><tr>'+['metal','crystal','eonium'].map(k=>'<td>'+nfmt(r.salvage?.[k])+'</td>').join('')+'</tr></tbody></table><small>'+ (r.earthSalvage?'Earth receives all 20% bonus salvage from destroyed attackers and defenders. '+esc(r.earthSalvage.status||'Settlement pending'):'No eligible Earth fleet participated; no bonus salvage.') +'</small><button class="btn" data-battle-calculator="'+esc(r.id)+'">OPEN IN BATTLE CALCULATOR · TWEAK FLEETS</button></section>';}
function openBattleNews(id){const r=state.news.find(x=>x.battleReport?.id===id)?.battleReport||(state.uplinkTestBattles||[]).find(r=>r.id===id);if(!r)return;window.bcalc={a:copy(r.attacker),d:copy(r.defender),population:r.population?.before??1000,biodomes:r.habitat?.before||0,biodomeDamage:r.habitat?.damageBefore||0};window.bcalcResult='Original engagement at '+esc(displayCoords(r.coords))+' · tick '+r.tick+'. Edit the starting fleets and calculate again.';allianceTab='bcalc';renderAlliance();navigate('alliance');}
function tickerControlsHTML(){return '<section class="panel" style="margin-bottom:14px"><div class="ph"><div class="pt">ROUND TICKER</div><span class="meta">'+(state.config.tickerStopped?'STOPPED':state.config.tickerPaused?'PAUSED':'RUNNING')+' · TICK '+state.tick+'</span></div><div id="tickerStatusBox">'+tickerStatusHTML()+'</div><div class="controls"><button class="btn primary" data-ticker="start">START</button><button class="btn" data-ticker="pause">PAUSE</button><button class="btn warn" data-ticker="stop">STOP</button><button class="btn" data-ticker="step">RUN ONE TICK</button><label class="field">Minutes per tick<input id="tickerMinutes" type="number" min="1" max="1440" step="1" value="'+(state.config.tickHours*60)+'"></label><button class="btn" data-ticker="speed">APPLY SPEED</button></div><div class="note" style="margin:12px">The practice ticker runs while this game is open and catches up at most 24 ticks after inactivity. Pausing freezes automatic ticks; restarting schedules a fresh interval.</div><div class="ticker-auto-start"><label class="field">Automatic start · local date and time<input id="tickerAutoStart" type="datetime-local" value="'+tickerAutoStartValue()+'"></label><button class="btn primary" data-ticker-auto="save">SCHEDULE START</button><button class="btn" data-ticker-auto="cancel">CANCEL SCHEDULE</button><span class="meta">'+(state.config.tickerAutoStartAt?'SCHEDULED: '+new Date(state.config.tickerAutoStartAt).toLocaleString():'NO AUTOMATIC START SCHEDULED')+' · Automatic starts do not unlock quests. This practice schedule runs when the game is open.</span></div></section>';}
function controlTicker(action){const wasPaused=!!state.config.tickerPaused;if(action==='start'&&state.tick>=state.roundLength)return notify('The round has ended.',true);if(action==='stop'){state.config.tickerPaused=true;state.config.tickerStopped=true;state.config.tickerPausedAt=Date.now();state.tickerQuestFlags=state.tickerQuestFlags||{};state.tickerQuestFlags.stop=true;}if(action==='pause'){state.config.tickerStopped=false;state.config.tickerPaused=true;state.config.tickerPausedAt=Date.now();}else if(action==='start'){state.tickerQuestFlags=state.tickerQuestFlags||{};if(state.tickerQuestFlags.start&&wasPaused)state.tickerQuestFlags.restart=true;state.tickerQuestFlags.start=true;state.config.tickerStopped=false;state.config.tickerPaused=false;state.config.tickerPausedAt=null;state.nextTickAt=Date.now()+gameTickMs();}else if(action==='step'){if(state.tick>=state.roundLength)return notify('The round has ended.',true);tickOnce();state.nextTickAt=Date.now()+gameTickMs();}else if(action==='speed'){const minutes=Number(document.getElementById('tickerMinutes').value);if(!Number.isFinite(minutes)||minutes<1||minutes>1440)return notify('Choose 1–1440 minutes.',true);state.config.tickHours=minutes/60;state.nextTickAt=Date.now()+gameTickMs();}if(['start','pause','stop'].includes(action)){const label={start:'STARTED',pause:'PAUSED',stop:'STOPPED'}[action];addNews('GAME UPDATE · Ticker '+label+' at tick '+state.tick+'.','warn');state.news[0].category='GAME_UPDATES';notify('Ticker '+label.toLowerCase()+'.');}state.tickerLastAction={message:{start:'Ticker started. Automatic ticks are enabled.',pause:'Ticker paused. Automatic ticks are frozen.',stop:'Ticker stopped. Automatic ticks are disabled.',step:'One tick processed successfully.',speed:'Tick interval updated.'}[action]||'Ticker updated.',at:Date.now()};update();save();shareStaffTickerSettings();}
document.addEventListener('click',e=>{const battle=e.target.closest('[data-battle-calculator]');if(battle)openBattleNews(battle.dataset.battleCalculator);const ticker=e.target.closest('[data-ticker]');if(ticker)controlTicker(ticker.dataset.ticker);});
function fitSidebarMenu(){const side=document.querySelector('.side'),nav=document.getElementById('nav');if(!side||!nav)return;for(const mode of ['normal','compact','dense']){side.dataset.density=mode;if(side.scrollHeight<=side.clientHeight+1&&nav.scrollHeight<=nav.clientHeight+1)break;}}
if(window.addEventListener)window.addEventListener('resize',fitSidebarMenu);document.querySelectorAll('#nav details').forEach(el=>el.addEventListener('toggle',fitSidebarMenu));if(typeof ResizeObserver!=='undefined'){const sidebar=document.querySelector('.side');if(sidebar)new ResizeObserver(fitSidebarMenu).observe(sidebar);}setTimeout(fitSidebarMenu,0);

document.addEventListener('change',e=>{const key=e.target.dataset?.quickSetting;if(!['allianceTaxEnabled','allianceScansEnabled'].includes(key))return;state.userSettings[key]=e.target.checked;save();renderPlanetSettings();renderWaves();notify('Alliance preference updated.');});

function questBonusBank(){state.questBonuses=state.questBonuses||{metal:0,crystal:0,eonium:0,research:0,construction:0,roids:{metal:0,crystal:0,eonium:0}};if(!state.startupBonusGranted){const rates={Terran:[125,95],Cathaar:[105,110],Xandathrii:[100,105],Zikonian:[115,95],Eitraides:[110,100]},rate=rates[state.race]||[100,100];for(const k of ['metal','crystal','eonium'])state.questBonuses[k]+=2000000;state.questBonuses.construction+=Math.floor(7000*rate[0]/100);state.questBonuses.research+=Math.floor(8000*rate[1]/100);state.startupBonusGranted=true;state.startupBonusRace=state.race;save();}return state.questBonuses;}
function questReward(q){if(q[4]?.reward)return resolveQuestReward(q[4].reward);if(q[3]==='population'||q[3]==='research:demography'){const tier=q[3]==='population'?[1050,1250,1500,2000,3000].indexOf(q[2]):q[2]-1,construction=[50,100,200,400,800][tier]||0,research=[100,150,250,400,600][tier]||0;return {metal:0,crystal:0,eonium:0,construction,research,roids:{metal:0,crystal:0,eonium:0}};}if(q[3]==='covert:strike'||q[3]==='covert:biodome'){const [construction,research]=({1:[100,200],5:[200,400],15:[400,800]})[q[2]]||[0,0];return {metal:0,crystal:0,eonium:0,construction,research,roids:{metal:0,crystal:0,eonium:0}};}if(q[3]==='building:biodome'){const rewards={1:[50,50],5:[150,100],15:[300,200],25:[500,350],50:[1000,700]},[construction,research]=rewards[q[2]]||[0,0];return {metal:0,crystal:0,eonium:0,construction,research,roids:{metal:0,crystal:0,eonium:0}};}if(q[3].startsWith('ticker:'))return {metal:0,crystal:0,eonium:0,research:0,construction:0,roids:{metal:1,crystal:1,eonium:1}};const metric=q[3],reward={metal:500,crystal:350,eonium:200,research:0,construction:0,roids:{metal:0,crystal:0,eonium:0}};if(metric.startsWith('research:')||metric.startsWith('scan'))reward.research=200;else if(metric.startsWith('building:')||metric==='buildings')reward.construction=200;else if(metric.startsWith('roid:'))reward.roids[metric.split(':')[1]]=1;else if(metric==='roids')reward.roids.metal=1;return reward;}
function questRewardText(q){const r=questReward(q);return [r.metal?r.metal+' Metal':'',r.crystal?r.crystal+' Crystal':'',r.eonium?r.eonium+' Eonium':'',r.research?r.research+' RP':'',r.construction?r.construction+' CU':'',...Object.entries(r.roids).filter(([,n])=>n).map(([k,n])=>n+' '+k+' asteroid')].filter(Boolean).join(' · ');}
function questLore(metric){if(metric==='population')return 'The census lights a new neighbourhood on the colonial map. The Development Ministry releases housing and research grants for its growing citizens.';if(metric==='research:demography')return 'The Green Ark programme links clinics, family services and habitat registries, bringing new settlers into the colony without exceeding its shelter capacity.';if(metric==='ticker:start')return 'The first pulse travels through the rebuilt Miday relay. Prospectors mark three asteroid fields as the Reach awakens.';if(metric==='ticker:stop')return 'Command seals the temporal relay to shelter the colonies. Emergency survey teams secure one field of each resource for the quiet hours.';if(metric==='ticker:restart')return 'The beacon burns again. As the suspended convoys resume their journey, three prospecting crews return with newly charted asteroid fields.';if(metric.startsWith('research:'))return 'The sealed Miday archive opens one more fragment as your scientists restore the lost technology.';if(metric.startsWith('building:')||metric==='buildings')return 'Vesper engineers raise a new beacon of industry among the ruins of the old jumpgate network.';if(metric.startsWith('roid'))return 'Prospectors follow the Starfall debris trail and recover supplies for the scattered colonies.';if(metric.startsWith('scan'))return 'A faint signal crosses the dark. Your listening arrays bring its message into focus.';if(metric.startsWith('setting:')||metric==='alliance')return 'The shared command charter asks each colony to sustain its allies through tribute and intelligence.';return 'The command offices record your service to the Vesper Reach and release a sealed supply warrant.';}
function questBonusHTML(){const b=questBonusBank();return '<section class="panel quest-bonus-bank" id="questBonusBank"><div class="ph"><div class="pt">'+newsIcon('ECONOMY')+' UNUSED QUEST BONUSES</div><span class="meta">CURRENT UNUSED BONUS</span></div><div class="note" style="margin:12px">Planetarion startup bonus imported once for ' + esc(state.startupBonusRace||state.race) + '. Base: 2,000,000 of each resource, 7,000 CU and 8,000 RP, with race adjustments. Loyalty bonus: 0% because previous-round history is unavailable. <a href="https://game.planetarion.com/manual.pl?page=formulae" target="_blank" rel="noopener">Manual source</a></div><div class="controls">'+['metal','crystal','eonium'].map(k=>'<span>'+esc(RES[k].label)+' · '+nfmt(b[k])+' resources / '+nfmt(b.roids[k])+' asteroids</span>').join('')+'<button class="btn primary" data-quest-bonus="accept">ACCEPT RESOURCES / ASTEROIDS</button></div><div class="ph"><div class="pt">RESEARCH · '+nfmt(b.research)+' RP TO ALLOCATE</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Branch</th><th>Next research</th><th>Current RP / total</th><th>Remaining RP</th><th>Allocate RP</th></tr></thead><tbody>'+TECH_TREE.map(t=>{const level=state.research[t.id]||0,max=level>=researchMax(t.id),progress=state.researchProgress[t.id]||0,cost=researchCost(t.id,level+1);return '<tr><td>'+esc(t.name)+'</td><td>'+esc(max?'Complete':t.levels[level]||t.name)+'</td><td>'+nfmt(progress)+' / '+(max?'—':nfmt(cost))+'</td><td>'+(max?'—':nfmt(cost-progress))+'</td><td><input type="number" min="0" step="1" value="0" data-bonus-rp="'+t.id+'" '+(max?'disabled':'')+' aria-label="Allocate RP to '+esc(t.name)+'"></td></tr>';}).join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-quest-bonus="research">ALLOCATE RESEARCH POINTS</button></div><div class="ph"><div class="pt">POPULATION RESERVE · '+nfmt(b.population||0)+' SETTLERS · CONSTRUCTIONS · '+nfmt(b.construction)+' CU TO ALLOCATE</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Construction</th><th>Built</th><th>Current CU / total</th><th>Remaining CU</th><th>Allocate CU</th></tr></thead><tbody>'+Object.entries(BUILDINGS).map(([id,d])=>{const current=state.bonusConstructionProgress?.[id]||0;return '<tr><td>'+esc(d.name)+'</td><td>'+nfmt(state.buildings[id])+'</td><td>'+nfmt(current)+' / '+nfmt(d.cu)+'</td><td>'+nfmt(d.cu-current)+'</td><td><input type="number" min="0" step="1" value="0" data-bonus-cu="'+id+'" aria-label="Allocate CU to '+esc(d.name)+'"></td></tr>';}).join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-quest-bonus="construction">ALLOCATE CONSTRUCTION UNITS</button></div><div class="note" style="margin:12px">Allocations are final. You can allocate partial progress or several levels and buildings at once. Unused points remain banked. Construction limits still apply; queued paid projects keep their progress.</div></section>';}
function allocateQuestBonus(action){const bank=questBonusBank();if(action==='accept'){const people=Math.min(bank.population||0,Math.max(0,populationCapacity()-state.population));state.population+=people;bank.population=(bank.population||0)-people;for(const k of ['metal','crystal','eonium']){state.resources[k]+=bank[k];state.roids[k]+=bank.roids[k];bank[k]=0;bank.roids[k]=0;}update();return;}const research=action==='research',selector=research?'[data-bonus-rp]':'[data-bonus-cu]',key=research?'research':'construction',entries=[...document.querySelectorAll(selector)].map(input=>({id:research?input.dataset.bonusRp:input.dataset.bonusCu,n:Number(input.value)}));if(entries.some(x=>!Number.isSafeInteger(x.n)||x.n<0))return notify('Enter whole, non-negative point amounts.',true);const total=entries.reduce((s,x)=>s+x.n,0);if(!total)return notify('Enter points to allocate.',true);if(total>bank[key])return notify('You cannot allocate more than your unused bonus.',true);const progress=copy(research?state.researchProgress:state.bonusConstructionProgress||{}),counts=copy(research?state.research:state.buildings);for(const {id,n} of entries){if(!n)continue;if(!research&&!bonusBuildingAvailable(id))return notify('Research has not unlocked this bonus structure. CU remains in your bank.',true);if(research&&!TECH_TREE.some(t=>t.id===id)||!research&&!BUILDINGS[id])return;let remaining=(progress[id]||0)+n,level=counts[id]||0;while(remaining>0){const cost=research?researchCost(id,level+1):BUILDINGS[id].cu;if(research&&level>=researchMax(id))return notify('That allocation exceeds the remaining research levels.',true);if(remaining<cost)break;remaining-=cost;level++;if(!research){counts[id]=level;if(Object.values(counts).reduce((a,v)=>a+v,0)>buildingLimit())return notify('Construction capacity would be exceeded. No points allocated.',true);}}counts[id]=level;progress[id]=remaining;}bank[key]-=total;if(research){const active=state.researchActive,completedActive=active&&(counts[active]||0)>(state.research[active]||0);state.research=counts;state.researchProgress=progress;if(completedActive||(active&&(counts[active]||0)>=researchMax(active)))state.researchActive=null;advanceResearchQueue();}else{state.buildings=counts;state.bonusConstructionProgress=progress;}addNews('Quest bonus allocated: '+total+' '+(research?'RP':'CU')+'.','good');update();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-quest-bonus]');if(button)allocateQuestBonus(button.dataset.questBonus);});

function newsTintClass(entry){if(newsCategory(entry)==='GAME_UPDATES')return 'news-game-update';if(newsCategory(entry)==='COVERT_OPS')return 'news-covert';if(entry.battleReport)return 'news-battle';if(newsCategory(entry)==='ALLIANCE')return 'alliance-signal';if(newsCategory(entry)==='RESEARCH')return 'news-research';if(/ship order|production|factory.*assigned|combined.*order/i.test(entry.text||''))return 'news-production';return ({FLEET:'news-fleet',ECONOMY:'news-economy',DEVELOPMENT:'news-development',INTELLIGENCE:'news-intelligence',POLITICS:'news-politics',SYSTEM:'news-system'})[newsCategory(entry)]||'';}

function achievementCategoryTabsHTML(){const selected=QUEST_CATEGORIES.some(c=>c.id===state.questCategory)?state.questCategory:QUEST_CATEGORIES[0].id;state.questCategory=selected;return '<nav class="achievement-category-tabs" aria-label="Achievement categories">'+QUEST_CATEGORIES.map(c=>'<button class="btn '+(c.id===selected?'active':'')+'" data-achievement-category="'+c.id+'">'+esc(c.shortName||c.name)+' <small>'+c.quests.filter(q=>q[3]!=='offsite'&&questValue(q[3])>=q[2]&&!state.questClaims[q[0]]).length+'</small></button>').join('')+'</nav>';}
function applyQuestTab(){const view=state.questView==='bonuses'?'bonuses':state.questView==='category'?'category':'board',content=document.getElementById('questContent');content.dataset.view=view;content.hidden=view==='board';document.querySelectorAll('[data-quest-category]').forEach(e=>e.hidden=view!=='category'||e.dataset.questCategory!==state.questCategory);document.querySelectorAll('[data-achievement-category]').forEach(e=>e.classList.toggle('active',view==='category'&&e.dataset.achievementCategory===state.questCategory));document.querySelectorAll('[data-quest-tab]').forEach(e=>e.classList.toggle('active',e.dataset.questTab===view));document.getElementById('questSummary').hidden=view!=='board';content.querySelector?.('.quest-lore')?.setAttribute?.('hidden','');content.querySelector?.('.quest-claim-all')?.setAttribute?.('hidden','');const bank=content.querySelector?.('.quest-bonus-bank');if(bank)bank.hidden=view!=='bonuses';}
document.addEventListener('click',e=>{const button=e.target.closest('[data-quest-tab]');if(button){state.questView=button.dataset.questTab;applyQuestTab();}});

const COVERT_OPS=[['fist','Exploding Fist',0,9],['agents','Agent Defection',1,15],['guards','Security Guard Defection',2,5],['science','Hacking: Science Database',3,10],['warp','Warp Drive Manipulation',4,5],['blackout','Information Blackout',5,15],['havoc','Havoc',6,10],['resources','Hacking: Resource Transfers',7,5],['government','Government Subversion',8,20],['strike','Worker Bribery · Quiet Picket',3,10],['biodome','Biodome Sabotage · Glassfall',6,15]];
function covertState(){state.covert=state.covert||{agents:0,guards:0,stealth:80,history:[],successes:0};return state.covert;}
function covertRace(race){return ({Terran:[80,8],Cathaar:[80,8],Xandathrii:[80,6],Zikonian:[85,6],Eitraides:[85,6]})[race]||[80,8];}
function covertAlert(p){const own=p?.player,guards=own?covertState().guards:(p?.guards||0),roids=own?state.roids:p?.roids||{},security=own?state.workforce.security:p?.workforce?.security||0,centres=own?state.buildings.securityCenter:p?.buildings?.securityCenter||0,gov=own?currentGovernmentName():p?.government||'None',bonus=({Corporatism:-5,Democracy:-10,Nationalism:25,Socialism:0,Totalitarianism:15,Anarchy:-15})[gov]||0;const base=(50+5*Math.min(guards/(totalRoids(roids)+1),15))*(1+((centres||0)*2.75+Math.min(50,security)+bonus)/100);return Math.max(base,p?.covertAlert||0);}
function tickCovert(){const c=covertState(),gov=({Democracy:10,Socialism:10})[currentGovernmentName()]||0,[max,growth]=covertRace(state.race);c.stealth=Math.min(max*(1+gov/100)+Math.min(5,c.successes||0),c.stealth+Math.round(growth*(1+gov/100)));const perAgent=1,perGuard=1;let available=Math.min(...Object.values(grossIncome()));while(c.guards&&c.guards*perGuard+c.agents*perAgent>available)c.guards--;while(c.agents&&c.guards*perGuard+c.agents*perAgent>available)c.agents--;for(const k of ['metal','crystal','eonium'])state.resources[k]=Math.max(0,state.resources[k]-c.guards*perGuard-c.agents*perAgent);for(const p of state.galaxy){if(p.covertAlert)p.covertAlert=Math.max(0,p.covertAlert-3);if(p.government==='Anarchy'&&p.governmentPending&&p.governmentRevolutionUntil<=state.tick){p.government=p.governmentPending;p.governmentPending=null;}}}
function renderCovert(){const el=document.getElementById('covertContent');if(!el)return;const c=covertState(),level=state.research.covert||0;el.innerHTML='<section class="panel covert-civil-lore"><div class="ph"><div class="pt">CIVIL OPERATIONS · THE QUIET FRONT</div></div><div class="settings-body"><p><b>Quiet Picket · Worker Bribery.</b> Couriers carry hardship credits and promises of better contracts. A peaceful walkout disrupts ore shipments: −10% mining income for 6 ticks, without population casualties. Covert level 3; at least 10 agents.</p><p><b>Glassfall · Biodome Sabotage.</b> Infiltrators compromise the Green Ark life-support lattice. Every 15 sent agents can destroy one known Biodome, costing its remaining resident places. Covert level 6; at least 15 agents.</p></div></section><section class="panel"><div class="ph"><div class="pt">'+newsIcon('INTELLIGENCE')+' AGENT COMMAND</div><span class="meta">INSTANT PRACTICE OPERATIONS</span></div><div class="alliance-kpis"><div class="alliance-kpi"><small>AGENTS</small><b>'+nfmt(c.agents)+'</b></div><div class="alliance-kpi"><small>GUARDS</small><b>'+nfmt(c.guards)+'</b></div><div class="alliance-kpi"><small>STEALTH</small><b>'+Math.floor(c.stealth)+'</b></div><div class="alliance-kpi"><small>ALERT</small><b>'+Math.floor(covertAlert(state.galaxy.find(p=>p.player)))+'</b></div></div><div class="controls"><label class="field">Personnel amount<input id="covertTrainAmount" type="number" min="1" max="100000" value="5"></label><button class="btn" data-covert-train="agents">TRAIN AGENTS</button><button class="btn" data-covert-train="guards">TRAIN GUARDS</button><button class="btn" data-covert-fire="agents">DISMISS AGENTS</button><button class="btn" data-covert-fire="guards">DISMISS GUARDS</button></div><div class="note" style="margin:12px">Starfall practice training: 500 of each resource per agent, 100 per guard. Wages: 1 of each resource per person per tick; guards are dismissed before agents if income cannot support them.</div></section><section class="panel" style="margin-top:14px"><div class="ph"><div class="pt">OPERATION ORDERS</div><span class="meta">COVERT RESEARCH LEVEL '+level+'</span></div><div class="controls"><label class="field">Target planet<select id="covertTarget">'+state.galaxy.filter(p=>!p.player&&p.status!=='Closed').map(p=>'<option value="'+esc(p.id)+'">'+esc(p.coords+' · '+p.name)+'</option>').join('')+'</select></label><label class="field">Operation<select id="covertOperation">'+COVERT_OPS.map(([id,name,req,min])=>'<option value="'+id+'" '+(level<req?'disabled':'')+'>'+esc(name)+' · '+min+' agents'+(level<req?' · LOCKED L'+req:'')+'</option>').join('')+'</select></label><label class="field">Agents to send<input type="number" id="covertSendAmount" min="5" max="100000" value="9"></label><button class="btn primary" data-covert-launch>EXECUTE OPERATION</button></div><div class="note" style="margin:12px">Mission charge: 500 of each resource per agent, including failed attempts. Protection, paused ticks, closed targets and insufficient stealth block launch. Outcomes are simulated in this browser’s practice round. <a href="https://game.planetarion.com/manual.pl?page=covertops" target="_blank" rel="noopener">Planetarion rules</a></div></section><section class="panel" style="margin-top:14px"><div class="ph"><div class="pt">OPERATION REPORTS</div></div>'+c.history.slice(0,20).map(r=>'<div class="note" style="margin:10px"><b>TICK '+r.tick+' · '+(r.success?'SUCCESS':'FAILED')+'</b><br>'+esc(r.operation+' · '+r.coords+' · '+r.agents+' agents · '+r.result)+'</div>').join('')+'</section>';}
function trainCovert(kind,fire=false){if(!['agents','guards'].includes(kind))return;const amount=Number(document.getElementById('covertTrainAmount').value);if(!Number.isSafeInteger(amount)||amount<1||amount>100000)return notify('Enter 1–100,000 personnel.',true);const c=covertState();if(fire)c[kind]=Math.max(0,c[kind]-amount);else{const cost=Object.fromEntries(['metal','crystal','eonium'].map(k=>[k,amount*(kind==='agents'?500:100)]));if(!canAfford(cost))return notify('Not enough resources for training.',true);pay(cost);c[kind]+=amount;}addNews('Covert command: '+(fire?'dismissed ':'trained ')+amount+' '+kind+'.','info');update();}
async function executeCovert(){const c=covertState(),op=COVERT_OPS.find(x=>x[0]===document.getElementById('covertOperation').value),p=state.galaxy.find(x=>x.id===document.getElementById('covertTarget').value),n=Number(document.getElementById('covertSendAmount').value);if(!op||!p||p.player||p.status==='Closed'||state.tick<=state.config.protectionTicks||state.config.tickerPaused||state.tick>=state.roundLength)return notify('Target unavailable, protection active, or ticks not running.',true);if((state.research.covert||0)<op[2])return notify('Research this operation first.',true);if(!Number.isSafeInteger(n)||n<op[3]||n>c.agents)return notify('Check the mission minimum and your available agents.',true);if(op[0]==='biodome'&&!(p.buildings?.biodome>0))return notify('No known Biodome on this target.',true);if(op[0]==='strike'&&p.strikeUntilTick>state.tick)return notify('This workforce is already on strike.',true);if(['strike','biodome'].includes(op[0])&&typeof runCivilCovert==='function'&&!window.isStaffWorkspace)return runCivilCovert(op,n,p);const newStealth=c.stealth-5-Math.floor(n*.5);if(newStealth<0)return notify('Agents refuse: recover your stealth first.',true);const bill={metal:500*n,crystal:500*n,eonium:500*n};if(!canAfford(bill))return notify('Not enough resources for the mission.',true);const alert=covertAlert(p);pay(bill);c.stealth=newStealth;const success=1+Math.floor(Math.random()*9)+newStealth-alert>1;let result='Detected; mission failed.';if(success){c.successes=(c.successes||0)+1;p.covertAlert=alert+20;result=applyCovertEffect(op[0],n,p);}else{c.successes=0;if(Math.random()<.5){c.agents-=n;result+=' '+n+' agents lost.';}}const xp=Math.floor(2*(op[2]+1+n/5));state.xp+=xp;const report={tick:state.tick,operation:op[1],coords:p.coords,agents:n,success,result:result+' · '+xp+' XP'};c.history.unshift(report);c.history=c.history.slice(0,100);addNews('Covert operation '+op[1]+' at '+p.coords+': '+report.result,success?'good':'warn');state.news[0].category='COVERT_OPS';update();}
function applyCovertEffect(id,n,p){const c=covertState();if(id==='strike'){p.strikeUntilTick=state.tick+6;c.strikes=(c.strikes||0)+1;return 'Quiet Picket: organisers offer hardship credits to entice workers into a strike. Mining income reduced by 10% for 6 ticks; ends at tick '+p.strikeUntilTick+'. No residents are killed.';}if(id==='biodome'){const before=Math.max(0,p.buildings?.biodome||0),destroyed=Math.min(before,Math.floor(n/15)),lost=Math.min(Math.max(0,(p.population??p.publicPopulation??planetBasePopulation(p))-planetBasePopulation(p)),Math.max(0,destroyed*50-Math.floor((p.biodomeDamage||0)/20)));p.buildings.biodome=before-destroyed;p.biodomeDamage=0;p.population=Math.max(0,(p.population??p.publicPopulation??1000)-lost);p.publicPopulation=p.population;if(destroyed)c.biodomeSabotages=(c.biodomeSabotages||0)+1;return 'Glassfall: operatives compromise the Green Ark life-support lattice. '+destroyed+' Biodome(s) destroyed; '+lost+' residents lost; housing capacity reduced by '+destroyed*50+'.';}p.resources=p.resources||{metal:0,crystal:0,eonium:0};p.roids=p.roids||{metal:0,crystal:0,eonium:0};if(id==='fist'){let left=Math.floor(n/3),lost=0;for(const k of ['metal','crystal','eonium']){const take=Math.min(p.roids[k]||0,left);p.roids[k]-=take;left-=take;lost+=take;}return lost+' asteroids destroyed.';}if(id==='agents'||id==='guards'){const key=id==='agents'?'agents':'guards',take=Math.min(p[key]||0,n*(id==='guards'?10:1));p[key]=(p[key]||0)-take;c[key]+=take;return take+' '+key+' defected.';}if(id==='science'){const branch=p.researchActive,progress=p.researchProgress?.[branch]||0,take=Math.min(progress,10*n,Math.floor(progress*Math.floor(n/4)/100));if(branch)p.researchProgress[branch]-=take;if(state.researchActive)state.researchProgress[state.researchActive]=(state.researchProgress[state.researchActive]||0)+take;return take+' RP removed'+(state.researchActive?' and transferred.':'; no active home research to receive them.');}if(id==='resources'){const ratio=npcValue(p)/Math.max(1,playerValue());let moved=0;for(const k of ['metal','crystal','eonium']){const take=Math.floor(Math.min((p.resources[k]||0)*.1,n*8000,n*2000*ratio));p.resources[k]-=take;state.resources[k]+=take;moved+=take;}return nfmt(moved)+' resources transferred.';}if(id==='government'){if(!p.government||p.government==='None')return 'Target has no government.';p.governmentPending=p.government;p.government='Anarchy';p.governmentRevolutionUntil=state.tick+Math.floor(n/5);return 'Government destabilized for '+Math.floor(n/5)+' ticks.';}if(id==='warp'){let budget=n*Math.floor(50+Math.min(npcValue(p)/Math.max(1,playerValue())*10,50))*100,lost=0;for(const [ship,qty] of Object.entries(p.ships||{})){const cost=Object.values(SHIPS[ship]?.cost||{}).reduce((s,v)=>s+v,0);if(!cost)continue;const take=Math.min(qty,Math.floor(budget/cost));p.ships[ship]-=take;budget-=take*cost;lost+=take;}return lost+' idle ships destroyed.';}p.buildings=p.buildings||{};let count=0;if(id==='blackout'){for(const key of ['waveAmplifier','waveDistorter']){const take=Math.min(p.buildings[key]||p[key]||0,Math.floor(n/15));p.buildings[key]=Math.max(0,(p.buildings[key]||p[key]||0)-take);p[key]=p.buildings[key];count+=take;}}else if(id==='havoc'){let budget=Math.floor(n/10);for(const key of Object.keys(p.buildings).filter(k=>!['waveAmplifier','waveDistorter'].includes(k))){const take=Math.min(p.buildings[key],budget);p.buildings[key]-=take;budget-=take;count+=take;}if(!Object.keys(p.buildings).length){count=Math.min(p.structures||0,budget);p.structures=(p.structures||0)-count;}}return count+' facilities destroyed.';}
document.addEventListener('click',e=>{const train=e.target.closest('[data-covert-train]'),fire=e.target.closest('[data-covert-fire]');if(train)trainCovert(train.dataset.covertTrain);if(fire)trainCovert(fire.dataset.covertFire,true);if(e.target.closest('[data-covert-launch]'))executeCovert();});

function refreshMilitaryClock(){const el=document.getElementById('militaryClock');if(!el)return;const d=new Date(),military=(date,utc)=>[utc?date.getUTCHours():date.getHours(),utc?date.getUTCMinutes():date.getMinutes(),utc?date.getUTCSeconds():date.getSeconds()].map(v=>String(v).padStart(2,'0')).join(':');el.textContent=military(d,false);const tickDisplay=document.getElementById('countdown');if(tickDisplay&&state.config.tickerStopped)tickDisplay.textContent='STOPPED';el.setAttribute('datetime',d.toISOString());const server=document.getElementById('serverMilitaryClock');if(server&&window.serverClockOffset!==undefined)server.textContent=military(new Date(Date.now()+window.serverClockOffset),true);const now=state.config.tickerPaused?(state.config.tickerPausedAt||Date.now()):Date.now(),percent=Math.max(0,Math.min(100,100*(1-(state.nextTickAt-now)/gameTickMs()))),fill=document.getElementById('tickProgressFill');if(fill){fill.style.width=(state.config.tickerStopped?0:percent).toFixed(2)+'%';fill.parentElement?.setAttribute?.('aria-valuenow',String(Math.floor(state.config.tickerStopped?0:percent)));const label=document.getElementById('tickProgressLabel');if(label)label.textContent=Math.floor(state.config.tickerStopped?0:percent)+'%';}const load=document.getElementById('pageLoadTime');if(load&&typeof performance!=='undefined'){const nav=performance.getEntriesByType?.('navigation')?.[0],duration=nav?.loadEventEnd||nav?.domContentLoadedEventEnd;if(duration)load.textContent='PAGE LOAD · '+Math.round(duration)+' ms';}}
refreshMilitaryClock();

async function syncServerClock(){if(typeof fetch==='undefined')return;const start=Date.now();try{const response=await fetch('/api/version',{cache:'no-store',credentials:'same-origin'}),data=await response.json(),end=Date.now();if(Number.isFinite(data.serverTime))window.serverClockOffset=data.serverTime-(start+end)/2;const el=document.getElementById('serverResponseTime');if(el)el.textContent='SERVER RTT · '+(end-start)+' ms';refreshMilitaryClock();}catch{const el=document.getElementById('serverResponseTime');if(el)el.textContent='SERVER · OFFLINE';}}syncServerClock();setInterval(syncServerClock,30000);

QUEST_CATEGORIES.push({id:'ticker',name:'Temporal command',quests:[['tickerFirstStart','Ignite the first tick',1,'ticker:start'],['tickerFirstStop','Secure the silent interval',1,'ticker:stop'],['tickerFirstRestart','Reawaken the Reach',1,'ticker:restart']]});


function questThemeFrame(){const skin=state.userSettings.skinRace||'Neutral';return ({Terran:'<path d="M8 8h14M8 8v14M56 8H42M56 8v14M8 56h14M8 56V42M56 56H42M56 56V42"/>',Cathaar:'<path d="M10 49 20 10M24 54 32 7M40 54 48 10" opacity=".4"/>',Xandathrii:'<path d="m32 3 26 14v30L32 61 6 47V17z"/>',Zikonian:'<path d="m32 3 28 29-28 29L4 32z"/>',Eitraides:'<path d="M6 32c0-25 52-25 52 0S6 57 6 32ZM32 4v56" opacity=".5"/>',LCARS:'<path d="M8 5h12v54H8M44 5h12v54H44" stroke-width="5"/>',Borg:'<path d="M5 5h54v54H5zM5 17h54M17 5v54M47 5v54M5 47h54"/>',Stargate:'<circle cx="32" cy="32" r="28"/><path d="m27 4 5 8 5-8M4 27l8 5-8 5m56-10-8 5 8 5"/>',DoctorWho:'<path d="M12 7h40v50H12zM12 17h40M32 17v40"/>',Battlestar:'<path d="M4 21 32 5l28 16M4 43l28 16 28-16"/>'})[skin]||'<circle cx="32" cy="32" r="28" stroke-dasharray="8 4"/>';}
function questGoalIcon(metric){const shape=metric.startsWith('ticker:')?'<circle cx="32" cy="32" r="16"/><path d="M32 21v12l9 6"/>':metric.startsWith('research:')?'<circle cx="29" cy="28" r="12"/><path d="m38 38 10 10M29 20v16m-8-8h16"/>':metric.startsWith('building:')||metric==='buildings'?'<path d="M16 47V30l11 6V23l10 8V16h11v31z"/>':metric.startsWith('roid')?'<path d="m29 15 16 7 6 15-11 14-21-4-6-19zM21 24l7 10 13-8M28 34l-2 11"/>':metric.startsWith('scan')||metric==='agents'||metric==='covertMissions'?'<circle cx="32" cy="32" r="18"/><path d="M32 14v18l14 10M14 32h18"/>':metric.startsWith('setting:')||metric==='alliance'?'<circle cx="25" cy="25" r="7"/><circle cx="42" cy="25" r="7"/><path d="M12 47c2-17 24-17 26 0m0-12c10-4 15 3 16 12"/>':'<path d="m32 14 6 12 14 3-10 10 2 14-12-7-12 7 2-14-10-10 14-3z"/>';return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+questThemeFrame()+shape+'</svg>';}
function questMedalIcon(claimed){return '<span class="quest-medal '+(claimed?'claimed':'completed')+'" title="'+(claimed?'Reward claimed · gold medal':'Objective completed · reward ready')+'" aria-label="'+(claimed?'Gold medal: reward claimed':'Completion medal')+'"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="m19 30-4 28 17-9 17 9-4-28" fill="currentColor" fill-opacity=".18"/><circle cx="32" cy="25" r="20" fill="currentColor" fill-opacity=".14"/><circle cx="32" cy="25" r="15"/><path d="m32 13 4 8 9 1-7 7 2 9-8-4-8 4 2-9-7-7 9-1z" fill="currentColor"/></svg></span>';}
function questRewardBadges(q){const r=questReward(q),parts=[];for(const k of ['metal','crystal','eonium'])if(r[k])parts.push('<span class="quest-reward-chip"><i class="quest-resource-icon '+k+'"></i>'+nfmt(r[k])+' '+esc(RES[k].label)+'</span>');if(r.research)parts.push('<span class="quest-reward-chip">'+questGoalIcon('research:core')+r.research+' RP</span>');if(r.construction)parts.push('<span class="quest-reward-chip">'+questGoalIcon('buildings')+r.construction+' CU</span>');for(const [k,n] of Object.entries(r.roids))if(n)parts.push('<span class="quest-reward-chip">'+questGoalIcon('roids')+n+' '+esc(k)+' asteroid</span>');if(r.population)parts.push('<span class="quest-reward-chip">+'+nfmt(r.population)+' settlers</span>');for(const [id,n] of Object.entries(r.structures||{}))parts.push('<span class="quest-reward-chip">'+n+' free '+esc(BUILDINGS[id].name)+'</span>');return parts.join('');}


function tickerAutoStartValue(){if(!state.config.tickerAutoStartAt)return '';const d=new Date(state.config.tickerAutoStartAt);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function scheduleTickerStart(action){if(action==='cancel'){state.config.tickerAutoStartAt=null;state.tickerLastAction={message:'Scheduled start cancelled.',at:Date.now()};update();shareStaffTickerSettings();return notify('Automatic start cancelled.');}const input=document.getElementById('tickerAutoStart').value,time=new Date(input).getTime();if(!input||!Number.isFinite(time)||time<=Date.now())return notify('Choose a future local date and time.',true);state.config.tickerAutoStartAt=time;state.tickerLastAction={message:'Automatic start scheduled for '+new Date(time).toLocaleString()+'.',at:Date.now()};addNews('GAME UPDATE · Automatic ticker start scheduled for '+new Date(time).toLocaleString()+'.','info');state.news[0].category='GAME_UPDATES';update();shareStaffTickerSettings();notify('Automatic start scheduled. No quest credit is awarded.');}
function processTickerAutoStart(){const time=state.config.tickerAutoStartAt;if(!time||Date.now()<time||state.tick>=state.roundLength)return;state.config.tickerAutoStartAt=null;state.config.tickerPaused=false;state.config.tickerStopped=false;state.config.tickerPausedAt=null;state.nextTickAt=Date.now()+gameTickMs();state.tickerLastAction={message:'Ticker started at the scheduled time.',at:Date.now()};addNews('GAME UPDATE · Ticker automatically STARTED at tick '+state.tick+'. Scheduled starts do not unlock quests.','warn');state.news[0].category='GAME_UPDATES';update();shareStaffTickerSettings();notify('Ticker automatically started.');}
document.addEventListener('click',e=>{const button=e.target.closest('[data-ticker-auto]');if(button)scheduleTickerStart(button.dataset.tickerAuto);});


function asteroidDraftBill(draft=state.asteroidDraft||{}){return Object.fromEntries(['metal','crystal','eonium'].map(k=>[k,draft[k]?costAsteroids(state.roids[k]||0,draft[k]):0]));}
function addAsteroidDraft(id){if(!RES[id])return;const qty=Number(document.getElementById('mine-'+id).value);if(!Number.isSafeInteger(qty)||qty<1)return notify('Enter a whole positive asteroid amount.',true);const draft=state.asteroidDraft=state.asteroidDraft||{},combined=(draft[id]||0)+qty;if(combined+(state.roids[id]||0)>mineLimit())return notify('The draft exceeds this resource’s mining capacity.',true);draft[id]=combined;save();renderAsteroidDraft();notify('Asteroids added to draft. Use Order all to confirm.');}
function renderAsteroidDraft(){const el=document.getElementById('asteroidDraft');if(!el)return;const draft=state.asteroidDraft||{},bill=asteroidDraftBill(),entries=Object.entries(draft).filter(([,n])=>n>0);el.innerHTML='<section class="panel" style="margin-top:12px"><div class="ph"><div class="pt">ASTEROID ORDER DRAFT</div><span class="meta">NOT CONFIRMED · NO RESOURCES CHARGED</span></div>'+(entries.length?'<table class="table"><thead><tr><th>Asteroid type</th><th>Amount</th><th>Cost</th><th></th></tr></thead><tbody>'+entries.map(([id,n])=>'<tr><td>'+esc(RES[id].label)+'</td><td>'+nfmt(n)+'</td><td>'+nfmt(bill[id])+' '+esc(RES[id].label)+'</td><td><button class="btn" data-remove-asteroid-draft="'+id+'">REMOVE</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">Add asteroid amounts above to prepare a combined order.</div>')+'<div class="controls"><span class="meta">TOTAL · '+constructionCostText(bill)+'</span><button class="btn primary" data-confirm-asteroid-draft '+(!entries.length?'disabled':'')+'>ORDER ALL</button><button class="btn" data-clear-asteroid-draft '+(!entries.length?'disabled':'')+'>CLEAR DRAFT</button></div><div class="note" style="margin:12px">Order all rechecks rising asteroid prices, resource balances and mining capacity. The complete draft is initiated together or left untouched.</div></section>';}
function confirmAsteroidDraft(){const draft=state.asteroidDraft||{},entries=Object.entries(draft).filter(([,n])=>n>0);if(!entries.length)return notify('Add asteroids to the draft first.',true);if(entries.some(([id,n])=>!RES[id]||!Number.isSafeInteger(n)||n<1||(state.roids[id]||0)+n>mineLimit()))return notify('Review the draft: an amount is invalid or exceeds capacity.',true);const bill=asteroidDraftBill(draft);if(!canAfford(bill))return notify('Not enough resources for the complete asteroid order. Draft preserved.',true);pay(bill);for(const [id,n] of entries)state.roids[id]+=n;state.asteroidDraft={};addNews('Combined asteroid order confirmed: '+entries.map(([id,n])=>n+' '+id).join(' · ')+'.','good');update();notify('All draft asteroids initiated.');refreshPageAfterOrder();}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-asteroid-draft]'),remove=e.target.closest('[data-remove-asteroid-draft]');if(add)addAsteroidDraft(add.dataset.addAsteroidDraft);if(remove){delete state.asteroidDraft[remove.dataset.removeAsteroidDraft];save();renderAsteroidDraft();}if(e.target.closest('[data-clear-asteroid-draft]')){state.asteroidDraft={};save();renderAsteroidDraft();}if(e.target.closest('[data-confirm-asteroid-draft]'))confirmAsteroidDraft();});


function claimCompletedQuests(category,questId){const categories=category?QUEST_CATEGORIES.filter(c=>(c.id||c.name)===category):QUEST_CATEGORIES,ready=categories.flatMap(c=>c.quests).filter(q=>(!questId||q[0]===questId)&&q[3]!=='offsite'&&!state.questClaims[q[0]]&&questValue(q[3])>=q[2]);if(!ready.length)return notify('No completed, unclaimed quests in this selection.');const bank=questBonusBank();for(const q of ready){state.questClaims[q[0]]=true;const r=questReward(q);applyExtraQuestReward(r,bank);state.questRewardReceipts=state.questRewardReceipts||{};state.questRewardReceipts[q[0]]=copy(r);for(const k of ['metal','crystal','eonium','research','construction'])bank[k]+=r[k]||0;for(const k of ['metal','crystal','eonium'])bank.roids[k]+=r.roids[k]||0;}addNews('Quest rewards claimed: '+ready.length+' completed '+(ready.length===1?'objective':'objectives')+'. Bonuses are ready to allocate.','good');attachAchievementReceipt(ready);update();notify(ready.length+' quest rewards added to Bonuses.');}
document.addEventListener('click',e=>{const category=e.target.closest('[data-claim-quest-category]');if(category)claimCompletedQuests(category.dataset.claimQuestCategory);if(e.target.closest('[data-claim-all-quests]'))claimCompletedQuests();});


function newsLore(entry){const category=newsCategory(entry),text=String(entry.text||'').toLowerCase();if(text.includes('vote'))return ['Electoral registrar','The ballots cross the Miday relay. The charter records the vote, and the command roster reflects its result.'];if(text.includes('government selection'))return ['Civil charter office','The new charter is sealed. Department heads align their production directives with the selected government.'];if(text.includes('tax')||text.includes('levy'))return ['Revenue office','The ledgers close on another transmission. Whole residents and resource receipts are recorded; unfinished fractions wait in the next ledger.'];if(entry.achievementReceipt)return ['Charter honours board','The sealed orders have been fulfilled. The treasury releases the itemised grants listed in this receipt.'];return ({ECONOMY:['Quartermaster','Freight beacons pulse across the resource lanes. The ledger below records the supplies and production figures reported by command.'],DEVELOPMENT:['Green Ark engineering','A new signal reaches the works district. Engineers file the construction outcome and keep the colony register aligned.'],RESEARCH:['Miday archive','Another fragment of the old archive comes into focus. The science office records exactly what the transmission has established.'],FLEET:['Flight control','Navigation lights cut through the dark. Fleet command records the order, route and available outcome in the attached report.'],BATTLE_REPORTS:['Combat recorder','The battlefield falls quiet long enough for the recorders to transmit. Losses and surviving units remain matters of the battle report below.'],COVERT_OPS:['Veiled relay','A coded message reaches the sealed operations desk. Command releases only the outcome recorded in this transmission.'],GAME_UPDATES:['Command network','The network distributes a revised command protocol. These recorded changes define the new operational instructions.'],INTELLIGENCE:['Listening station','A faint carrier breaks through the interference. Analysts preserve the received intelligence and its recorded limits.'],ALLIANCE:['Alliance liaison','The alliance relay carries another command signal. The names, declaration and recorded effects remain attached to the official report.'],POLITICS:['Galactic charter office','The council seals its command ledger. Appointments, votes and policy decisions are preserved in the transmission record.'],SYSTEM:['Command recorder','The command recorder acknowledges the signal. The reported action and its recorded state are entered in the colony journal.']})[category]||['Command recorder','The transmission enters the command journal.'];}
function newsFeedbackHTML(entry){if(entry.worldAnnouncement){const w=entry.worldAnnouncement;return '<section class="world-broadcast"><img src="/assets/planets/'+esc(w.worldId)+'.svg" alt="'+esc(w.title)+'"><div><small>PUBLIC REGISTRY · HOLDER & LOCATION SEALED</small><h3>'+esc(w.title)+'</h3>'+w.lore.map(p=>'<p>'+esc(p)+'</p>').join('')+'<b>'+esc(w.rarity)+' · Founding population '+nfmt(w.basePopulation)+' · ETA '+w.etaBonus+' tick · Bonus salvage '+w.salvageBonusPercent+'%</b></div></section>';}const [voice,line]=newsLore(entry),c=entry.context,details=entry.details&&typeof entry.details==='object'?Object.entries(entry.details).filter(([,v])=>['string','number','boolean'].includes(typeof v)):[],rows=c?[['Recorded by',c.actor||'Not recorded'],['Colony',c.planet||'Not recorded'],['Coordinates',c.coords?displayCoords(c.coords):'Not recorded'],['World',c.world||'Not recorded'],['Residents',nfmt(c.population)],['Population mining bonus','+'+Number(c.miningBonus||0).toFixed(3)+'%'],['Population work bonus','+'+(c.workBonus||0)+' CU / RP'],['Metal balance',nfmt(c.resources?.metal||0)],['Crystal balance',nfmt(c.resources?.crystal||0)],['Eonium balance',nfmt(c.resources?.eonium||0)],['XP',nfmt(c.xp||0)],...details]:details;return '<aside class="news-transmission-lore"><span>'+newsIcon(newsCategory(entry))+'</span><div><small>COMMAND ATMOSPHERE · '+esc(voice)+'</small><p>“'+esc(line)+'”</p></div></aside><div class="news-outcome-strip"><small>RECORDED OUTCOME</small><b>'+esc(newsStatus(entry)[0])+'</b><span>'+esc(entry.context?.actor||'Command journal')+'</span></div>'+(rows.length?'<details class="news-record-details"><summary>COLONY SNAPSHOT & EVENT DETAILS · AT TRANSMISSION</summary><dl>'+rows.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><p>Recorded colony state when this entry was created. Detailed battle, reward and diplomacy receipts above describe the event itself.</p></details>':'');}
function newsEventCard(x,index){const category=newsCategory(x),[label,status]=newsStatus(x),title=category.replaceAll('_',' '),date=x.at?new Date(x.at).toLocaleString():'ROUND START';return '<article class="news-entry news-event-card '+newsTintClass(x)+'"><header class="news-event-header"><div class="news-event-emblem news-entry-icon '+category.toLowerCase()+'">'+newsIcon(category)+'</div><div><span class="news-event-kicker">COMMAND TRANSMISSION · '+String(index+1).padStart(4,'0')+'</span><h3>'+esc(title)+'</h3></div><span class="news-status '+status+'">'+label+'</span></header><div class="news-event-body news-entry-copy"><span class="news-event-label">EVENT REPORT</span><p>'+esc(x.text||'Unknown event')+'</p>'+(x.diplomacy?diplomacyReportHTML(x.diplomacy):'')+(x.achievementReceipt?achievementReceiptHTML(x.achievementReceipt):'')+(x.battleReport?battleNewsHTML(x.battleReport):'')+newsFeedbackHTML(x)+'</div><footer class="news-event-meta"><div><span>TICK</span><b>'+String(x.tick||0).padStart(3,'0')+'</b></div><div><span>TRANSMISSION TIME</span><b>'+esc(date)+'</b></div><div><span>CATEGORY</span><b>'+esc(title)+'</b></div></footer></article>';}


async function loadUniverseIntel(){if(!mayAlliance('intel')||!state.universeIntelOverlay)return;if(typeof centralDirectoryRequest!=='function'){renderUniverse();return;}try{const data=await centralDirectoryRequest('/api/alliance-intel');if(data.alliance!==state.alliance.name)return;state.universeIntelOwner=data.alliance;state.universeIntelRecords=Object.fromEntries((data.records||[]).map(r=>[r.coords,r]));renderUniverse();}catch(error){state.universeIntelOverlay=false;state.universeIntelRecords={};renderUniverse();notify(error.message,true);}}
document.addEventListener('change',e=>{if(e.target.id==='universeIntelOverlay'){state.universeIntelOverlay=e.target.checked;state.universeFilter='all';save();renderUniverse();if(e.target.checked)loadUniverseIntel();}});


function autoClaimQuestRewards(){if(!state.userSettings?.autoClaimQuests)return 0;state.questAutomationStats=state.questAutomationStats||{total:0};state.questAutomationStats.lastCheckAt=Date.now();const ready=QUEST_CATEGORIES.flatMap(c=>c.quests).filter(q=>q[3]!=='offsite'&&!state.questClaims[q[0]]&&questValue(q[3])>=q[2]);if(!ready.length)return 0;const bank=questBonusBank();for(const q of ready){state.questClaims[q[0]]=true;const r=questReward(q);for(const k of ['metal','crystal','eonium','research','construction'])bank[k]+=r[k]||0;for(const k of ['metal','crystal','eonium'])bank.roids[k]+=r.roids[k]||0;}state.questAutomationStats.total+=ready.length;state.questAutomationStats.lastClaimAt=Date.now();state.questAutomationStats.lastClaimTick=state.tick;state.questAutomationStats.lastClaimCount=ready.length;addNews('Quest automation claimed '+ready.length+' completed rewards. Open Bonuses to allocate them.','good');attachAchievementReceipt(ready);return ready.length;}
document.addEventListener('change',e=>{if(e.target.id==='autoClaimQuestRewards'){const enabled=e.target.checked,before=state.questAutomationStats?.total||0;state.userSettings.autoClaimQuests=enabled;update();const count=(state.questAutomationStats?.total||0)-before;notify(enabled?'Automatic claiming ON. '+(count?count+' completed rewards added to Bonuses.':'No new completed rewards waiting; future completions will be banked.'):'Automatic claiming OFF.');}});


const TREK_POWERS=['Federation','Klingon','Romulan','Cardassian','Dominion','Borg','Ferengi','Breen'];
const TREK_NAMES={Federation:['USS Defiant','USS Voyager','USS Enterprise NX-01','USS Enterprise NCC-1701','USS Enterprise-A','USS Enterprise-D','USS Enterprise-E','USS Discovery','USS Titan-A','USS Enterprise-G'],Klingon:['IKS Bounty','IKS Pagh','IKS Rotarran','IKS Ch’Tang','IKS Hegh’ta','IKS Negh’Var','IKS Bortas','IKS T’Ong','IKS Koraga','IKS Sarcophagus'],Romulan:['IRW Khazara','IRW T’Met','IRW Devoras','IRW Haakona','IRW Terix','IRW Valdore','IRW Scimitar','IRW Narada','IRW D’Deridex','IRW Tal Shiar'],Cardassian:['CDS Prakesh','CDS Trager','CDS Vetar','CDS Reklar','CDS Aldara','CDS Kraxon','CDS Galor','CDS Keldon','CDS Bok’Nor','CDS Ravinok'],Dominion:['Jem’Hadar Vanguard','Jem’Hadar Interceptor','Jem’Hadar Strike Wing','Jem’Hadar Escort','Jem’Hadar Attack Ship','Jem’Hadar Battlecruiser','Jem’Hadar Dreadnought','Founder’s Will','Vorta Command','Dominion Flagship'],Borg:['Probe Alpha','Sphere One','Tactical Cube','Assimilation Cube','Queen’s Vessel','Unimatrix One','Diamond Command','Collective Vanguard','Cube 001','Nexus Prime'],Ferengi:['Kreechta','Krayton','D’Kora','Marauder Profit','Grand Nagus','Divine Treasury','Latinum Venture','Commerce Raider','Acquisition Prime','Fortune’s Edge'],Breen:['Gor’s Command','Thot’s Spear','Chel Grett','Rezreth','Sarr Theln','Absolute Zero','Cold Dominion','Polar Vanguard','Cryonic Blade','Breen Flagship']};
const originalFleetNames=Object.fromEntries(Object.entries(SHIPS).map(([id,d])=>[id,d.name]));
function trekPower(){const selected=state.userSettings.trekFleetPower;if(TREK_POWERS.includes(selected))return selected;if(state.userSettings.skinRace==='Borg')return 'Borg';return ({Terran:'Federation',Cathaar:'Klingon',Xandathrii:'Romulan',Zikonian:'Cardassian',Eitraides:'Dominion'})[state.race]||'Federation';}
function trekRegistry(id){return trekPower().slice(0,3).toUpperCase()+'-'+String(Object.keys(SHIPS).indexOf(id)+1).padStart(3,'0');}
function applyTrekFleetNames(){const enabled=!!state.userSettings.trekFleetEnabled;document.body.dataset.trekFleet=enabled?'on':'off';document.body.dataset.trekPower=trekPower();let n=0;for(const [id,d] of Object.entries(SHIPS)){if(d.race!==state.race){d.name=originalFleetNames[id];continue;}d.name=enabled?TREK_NAMES[trekPower()][n%10]+(n>=10?' · '+d.class:''):originalFleetNames[id];n++;}}
document.addEventListener('change',e=>{if(e.target.id==='trekFleetEnabled'||e.target.id==='trekFleetPower'){state.userSettings[e.target.id]=e.target.id==='trekFleetEnabled'?e.target.checked:e.target.value;update();notify('Fleet appearance updated.');location.hash='planetSettings';location.reload();}});


async function savePlanetIdentity(field){const id=field==='planetName'?'planetDisplayName':'planetRulerName',value=(document.getElementById(id)?.value||'').trim();if(value.length<2||value.length>60||!/^['’\p{L}\p{N} _.-]+$/u.test(value))return notify('Use 2–60 plain letters, numbers, spaces, dots, apostrophes, underscores or hyphens.',true);try{if(typeof centralDirectoryRequest==='function'){const result=await centralDirectoryRequest('/api/planets',{[field]:value},'PATCH');planetDirectoryRevision=result.revision;}const home=state.galaxy.find(p=>p.player);if(home){const oldName=home.name;if(field==='planetName'){home.name=value;for(const a of [state.alliance,...state.allianceDirectory||[]])for(const member of a.members||[])if(member.planetId===home.id||member.planet===oldName)member.planet=value;}else home.ruler=value;}update();notify(field==='planetName'?'Planet name saved.':'Ruler name saved.');}catch(error){notify(error.message,true);}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-save-planet-identity]');if(button)savePlanetIdentity(button.dataset.savePlanetIdentity);});

function universePopulation(p){return p.player?state.population:Math.max(0,Number(p.population??p.publicPopulation)||0);}
function universeSize(p){return p.player?totalRoids(state.roids):p.roids?totalRoids(p.roids):Number(p.publicSize)||0;}
function universeSnapshot(){const planets=state.galaxy.filter(p=>!p.exiled).map(p=>({id:p.id,size:universeSize(p),score:planetScore(p),value:p.player?playerValue():npcValue(p),population:universePopulation(p)}));state.universeHistory=state.universeHistory||[];const snapshot={tick:state.tick,at:Date.now(),planets},last=state.universeHistory.at(-1);if(last?.tick===state.tick)state.universeHistory[state.universeHistory.length-1]=snapshot;else state.universeHistory.push(snapshot);state.universeHistory=state.universeHistory.slice(-169);return snapshot;}
function universeModule(title,columns,rows,tint='cyan',note=''){return '<section class="panel universe-module '+tint+'"><div class="ph"><div class="pt">'+title+'</div></div><div class="table-wrap"><table class="table"><thead><tr>'+columns.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+ (rows.length?rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+columns.length+'" class="empty">No recorded data yet.</td></tr>')+'</tbody></table></div>'+(note?'<p class="universe-module-note">'+note+'</p>':'')+'</section>';}
