const raceRows=RACE_SKINS.map(r=>{const members=active.filter(p=>p.race===r),share=active.length?Math.round(members.length/active.length*100):0;return [esc(r),members.length,'<div class="universe-race-bar" style="--share:'+share+'%"><span>'+share+'%</span></div>',nfmt(members.reduce((n,p)=>n+universeSize(p),0))];});html+=universeModule('CIVILISATION DISTRIBUTION',['Race','Planets','Share','Size'],raceRows,'green');const ratio=[...active].filter(p=>universeSize(p)>0).sort((a,b)=>(b.player?playerValue():npcValue(b))/universeSize(b)-(a.player?playerValue():npcValue(a))/universeSize(a)).slice(0,10).map((p,i)=>[i+1,planetCell(p),nfmt(universeSize(p)),((p.player?playerValue():npcValue(p))/universeSize(p)).toFixed(2)]);html+=universeModule('VALUE / ASTEROID',['#','Planet','Size','Ratio'],ratio,'gold','Ratio = current value divided by asteroid count.');
for(const [title,key,direction,tint] of [['LARGEST GROWERS · ASTEROIDS','size',1,'green'],['LARGEST LOSERS · ASTEROIDS','size',-1,'red'],['VALUE GAINED','value',1,'gold'],['VALUE LOST · CRASHERS','value',-1,'orange'],['POPULATION GROWERS','population',1,'green'],['POPULATION LOSERS','population',-1,'red']]){const rows=active.filter(p=>delta(p)[key]*direction>0).sort((a,b)=>(delta(b)[key]-delta(a)[key])*direction).slice(0,10).map((p,i)=>[i+1,planetCell(p),signed(delta(p)[key])]);html+=universeModule(title,['#','Planet','Change'],rows,tint,'Recorded window: '+tracked+' ticks (maximum 24). History starts when this browser observes the round.');}
