function isOwnAllianceMember(member){const home=state.galaxy.find(p=>p.player);return !!home&&home.alliance===state.alliance.name&&(member.planetId===home.id||member.planet===home.name);}
function queueAllianceStructure(type,slot){const a=state.alliance,d=STRUCTURE_DEFS[type];if(!d||!mayAlliance('structures'))return notify('Your rank cannot build alliance structures.',true);if(!a.fortress.strongholdGalaxy||!a.tax)return notify('Set the stronghold and alliance tax first.',true);const queue=a.structures.buildQueue=a.structures.buildQueue||[];if(!availableStructureSlots().includes(slot))return notify('Choose an available structure slot.',true);if(queue.some(x=>x.type===type)||a.structures.active.some(x=>x.type===type)||state.tick<(a.structures.cooldowns[type]||0))return notify('This structure is already building, active or cooling down.',true);const cost=structureCost(type);if(!Object.entries(cost).every(([k,n])=>(a.fund[k]||0)>=n))return notify('Alliance fund cannot cover this structure.',true);for(const [k,n] of Object.entries(cost))a.fund[k]-=n;const id='structure-'+type+'-'+Date.now(),build={id,type,slot,startedAt:state.tick,completesAt:state.tick+3};queue.push(build);state.structurePlanets.push({...build,building:true,structurePlanet:true,typeName:d.name,name:d.name+' Structure Planet',ruler:a.name,alliance:a.name,coords:a.fortress.strongholdGalaxy+':'+String(slot).padStart(2,'0'),ships:{},resources:{metal:0,crystal:0,eonium:0},roids:{metal:0,crystal:0,eonium:0}});a.structures.history.unshift({name:d.name,message:'Construction started in slot '+slot+'; completes at tick '+build.completesAt,tick:state.tick});allianceLogAction(d.name+' construction started. Ready in 3 ticks.');update();refreshPageAfterOrder();}
function completeAllianceStructureBuilds(){const a=state.alliance,queue=a.structures.buildQueue||[];for(const build of queue.filter(x=>state.tick>=x.completesAt)){const planet=state.structurePlanets.find(p=>p.id===build.id),d=STRUCTURE_DEFS[build.type];if(!planet||!d)continue;planet.building=false;if(d.duration){const effect={id:build.id,type:build.type,name:d.name,slot:build.slot,alliance:a.name,startedAt:state.tick,expiresAt:state.tick+(d.durationUnit==='hours'?allianceHoursToTicks(d.duration):d.duration)};a.structures.active.push(effect);planet.expiresAt=effect.expiresAt;if(d.cooldown)a.structures.cooldowns[build.type]=state.tick+d.cooldown;allianceLogAction(d.name+' completed in slot '+build.slot+'; effect is now active.','good');}else{distributeAllianceBuilding(build.type==='voyagerIV'?'waveAmplifier':'waveDistorter',5);state.structurePlanets=state.structurePlanets.filter(p=>p.id!==build.id);allianceLogAction(d.name+' completed; every alliance member received 5 '+(build.type==='voyagerIV'?'Wave Amplifiers':'Wave Distorters')+'.','good');}a.structures.history.unshift({name:d.name,message:'Completed after 3 ticks in slot '+build.slot,tick:state.tick});}a.structures.buildQueue=queue.filter(x=>state.tick<x.completesAt);}
function structureBuildProgress(build){const elapsed=Math.min(3,Math.max(0,state.tick-build.startedAt)),percent=Math.round(elapsed/3*100);return '<div class="structure-progress" role="progressbar" aria-label="'+esc(STRUCTURE_DEFS[build.type]?.name||'Structure')+' construction" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+percent+'"><i style="width:'+percent+'%"></i></div><small>BUILDING · '+elapsed+' / 3 TICKS · '+Math.max(0,build.completesAt-state.tick)+' TICKS LEFT</small>';}
function renderOverviewAllianceStructures(){const el=document.getElementById('overviewAllianceStructures');if(!el)return;const a=state.alliance,active=isAllianceMember('A. Commander')?a.structures.active:[],queue=isAllianceMember('A. Commander')?(a.structures.buildQueue||[]):[];el.innerHTML='<div class="ph"><div class="pt">ALLIANCE STRUCTURES</div><span class="meta">'+active.length+' ACTIVE · '+queue.length+' BUILDING</span></div><div class="overview-structure-art"><small>STRONGHOLD COMMAND</small><b>'+esc(a.name)+'</b></div><div class="overview-structure-grid">'+active.map(x=>{const total=Math.max(1,x.expiresAt-x.startedAt),remaining=Math.max(0,x.expiresAt-state.tick),percent=Math.round(remaining/total*100);return '<article class="overview-structure-box">'+structureGlyph(x.type)+'<div><h3>'+esc(STRUCTURE_DEFS[x.type].name)+'</h3><p>'+esc(STRUCTURE_DEFS[x.type].desc)+'</p><div class="structure-progress" role="progressbar" aria-label="Active effect remaining" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+percent+'"><i style="width:'+percent+'%"></i></div><small>ACTIVE · SLOT '+x.slot+' · '+remaining+' TICKS LEFT</small></div></article>';}).join('')+queue.map(x=>'<article class="overview-structure-box building">'+structureGlyph(x.type)+'<div><h3>'+esc(STRUCTURE_DEFS[x.type].name)+'</h3>'+structureBuildProgress(x)+'</div></article>').join('')+(!active.length&&!queue.length?'<div class="empty">No active or building alliance structures.</div>':'')+'</div><div class="controls"><button class="btn" data-open-alliance-structures>OPEN ALLIANCE STRUCTURES</button></div>';}
