async function loadOwnerSettings(){const input=document.getElementById('ownerPasskey');if(!input)return;if(ownerPasskeyAlliance!==state.alliance.name)ownerPasskeyMemory='';if(ownerPasskeyMemory){input.value=ownerPasskeyMemory;const status=document.getElementById('ownerKeyStatus');if(status)status.textContent='Personal key ready.';return;}if(ownerSettingsPending||typeof centralDirectoryRequest!=='function')return;ownerSettingsPending=true;const requestedAlliance=state.alliance.name;try{const result=await centralDirectoryRequest('/api/alliance-control/settings');if(state.alliance.name!==requestedAlliance)return;ownerPasskeyAlliance=requestedAlliance;ownerPasskeyMemory=result.passkey||'';const current=document.getElementById('ownerPasskey');if(current)current.value=ownerPasskeyMemory;const status=document.getElementById('ownerKeyStatus');if(status)status.textContent=result.isOwner?'Personal key ready.':'Owner access required.';}catch(error){const status=document.getElementById('ownerKeyStatus');if(status)status.textContent=error.message;}finally{ownerSettingsPending=false;}}
async function saveAllianceSetting(key){try{await syncPlanetDirectory();await centralDirectoryRequest('/api/alliance-control/settings',{[key]:document.getElementById('allySetting-'+key).value,revision:planetDirectoryRevision});applySharedDirectory(await centralDirectoryRequest('/api/planets'));notify('Alliance setting saved.');}catch(error){notify(error.message,true);}}
async function recreateAlliance(){const passkey=document.getElementById('allianceRestorePasskey')?.value||'';try{await centralDirectoryRequest('/api/alliance-control/recreate',{passkey});if(document.getElementById('allianceRestorePasskey'))document.getElementById('allianceRestorePasskey').value='';ownerPasskeyMemory='';applySharedDirectory(await centralDirectoryRequest('/api/planets'));state.allianceCreated=true;allianceTab='settings';update();navigate('alliance');notify('Alliance configuration restored.');}catch(error){notify(error.message,true);}}
