function testBattleUplinkHTML(){if(state.siteManagement?.battleCalcTest===false)return '';return '<section class="panel" id="uplinkTestLab"><div class="ph"><div class="pt">SIMULATED BATTLE LAB</div><span class="tag gold">TEST DATA · LOCAL</span></div><div class="settings-body"><p>Generated practice battles test reports and calculator. Reports remain in this test module. No real ships, resources or farming audit events are changed.</p><button class="btn primary" data-simulate-test-battle>SIMULATE RANDOM BATTLE</button><div id="uplinkTestBattleReports">'+(state.uplinkTestBattles||[]).map(r=>'<article class="fleet-member-box"><h3>SIMULATED · '+esc(r.attackerName)+' vs '+esc(r.defenderName)+'</h3>'+battleNewsHTML(r)+'</article>').join('')+'</div></div></section>';}
function simulateUplinkBattle(){if(state.siteManagement?.battleCalcTest===false)return notify("Battle test is disabled by Site management.",true);const races=[...new Set(Object.values(SHIPS).map(d=>d.race))],aRace=races[Math.floor(Math.random()*races.length)],dRace=races[Math.floor(Math.random()*races.length)],fleet=race=>{const ids=Object.entries(SHIPS).filter(([,d])=>d.race===race&&!d.pod);const ships={};for(let i=0;i<3;i++){const id=ids[Math.floor(Math.random()*ids.length)]?.[0];if(id)ships[id]=(ships[id]||0)+10+Math.floor(Math.random()*41);}return ships;},a=fleet(aRace),d=fleet(dRace),home=state.galaxy.find(p=>p.player),target={name:'SIMULATED defender',coords:home?.coords||'07:04:01'},fight=resolveCombat(copy(a),copy(d),'Simulated attacker','Simulated defender');const report=recordSimulatedCalculatorReport(fight,'Random test engagement');report.attackerName='SIMULATED test fleet';report.defenderName='SIMULATED defender';report.source='uplink';report.simulated=true;report.attackerRace=aRace;report.defenderRace=dRace;state.uplinkTestBattles=[copy(report),...(state.uplinkTestBattles||[])].slice(0,3);save();update();const root=document.getElementById('midayContent');if(root&&typeof buildMidayPage==='function'){buildMidayPage();if(typeof renderMidayReports==='function')renderMidayReports();}notify('Simulated battle added to Satelite Uplink.');return report;}
document.addEventListener('click',e=>{if(e.target.closest('[data-simulate-test-battle]'))simulateUplinkBattle();});
function showAllianceCreatedConfirmation(a,disclosure){const panel=document.createElement('section');panel.className='panel alliance-created-confirmation';panel.setAttribute('role','status');panel.innerHTML='<div class="ph"><div class="pt">✓ ALLIANCE CREATED</div><span class="tag green">OWNER ACCESS CONFIRMED</span></div><div class="settings-body"><h3>'+esc(a.name)+' ['+esc(a.tag)+']</h3><p>Your rank: <b>Owner</b>. Your personal encrypted key has been generated.</p><p>Staff disclosure: <b>'+(disclosure?'Enabled with your passphrase':'Disabled')+'</b>.</p><button class="btn primary" data-created-alliance-settings>OPEN ALLIANCE SETTINGS</button><button class="btn" data-dismiss-alliance-created>DISMISS</button></div>';const previous=document.querySelector('.alliance-created-confirmation');if(previous)previous.remove();document.getElementById('page-alliance').prepend(panel);}
