function recordSimulatedCalculatorReport(fight,title){const clean=String(title).replace(/[^\p{L}\p{N} _.:-]/gu,'').slice(0,80)||'Calculator engagement',report={id:'calc-'+Date.now()+'-'+Math.random().toString(36).slice(2),tick:state.tick,coords:'SIMULATION',target:clean,attackerName:'SIMULATED calculator attacker',defenderName:'SIMULATED '+clean,attacker:copy(fight.arrivedA),defender:copy(fight.arrivedD),survivorsA:copy(fight.attacker),survivorsD:copy(fight.defender),population:{before:fight.populationBefore,lost:fight.populationLost,after:fight.populationAfter},salvage:{metal:0,crystal:0,eonium:0},simulated:true,source:'calculator'};report.earthSalvage=earthBattleSalvage(report,{});if(report.earthSalvage){report.salvage=report.earthSalvage.award;report.earthSalvage.status="SIMULATED ONLY · no resources credited";}window.bcalcReport=report;return report;}
function resetTickerAfterRoundReset(){state.config.tickerPaused=true;state.config.tickerStopped=true;state.config.tickerPausedAt=Date.now();state.config.tickerAutoStartAt=null;state.nextTickAt=Date.now()+gameTickMs();}
