function bcalcSheetHTML(saved){return '<section class="panel bcalc-sheet"><div class="ph"><div class="pt">FLEET WORKSHEET</div><span class="meta">TAB · ARROW KEYS · PASTE FROM SPREADSHEET</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Ship / class</th><th>Attacker</th><th>Defender</th><th>Population dmg</th></tr></thead><tbody>'+Object.entries(SHIPS).map(([id,d])=>'<tr data-ship-class="'+esc(d.class)+'"><td><b>'+esc(d.name)+'</b><small>'+esc(d.class)+' · '+esc(d.race)+'</small></td>'+['a','d'].map(side=>'<td><input aria-label="'+esc(d.name)+' '+(side==='a'?'attacker':'defender')+'" type="number" min="0" max="1000000000" data-cship="'+side+'" data-ship="'+id+'" value="'+(saved[side][id]||0)+'"></td>').join('')+'<td>'+(['Cruiser','Battleship'].includes(d.class)?populationDamageLabel(d):'')+'</td></tr>').join('')+'</tbody></table></div><p class="note">Paste numeric cells starting at the selected count. Two columns map to Attacker and Defender. Arrow keys move between cells; Tab advances normally.</p></section>';}
document.addEventListener('keydown',e=>{if(!e.target.matches('.bcalc-sheet [data-cship]')||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;const rows=[...document.querySelectorAll('.bcalc-sheet tbody tr')],row=e.target.closest('tr'),r=rows.indexOf(row),col=e.target.dataset.cship==='a'?0:1,nextR=r+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0),nextC=col+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0),input=rows[nextR]?.querySelectorAll('input')[nextC];e.preventDefault();if(input){input.focus();input.select();}});
document.addEventListener('paste',e=>{if(!e.target.matches('.bcalc-sheet [data-cship]'))return;const text=e.clipboardData.getData('text');if(!/[\t\n]/.test(text))return;e.preventDefault();const values=text.trim().split(/\r?\n/).map(line=>line.split('\t').map(v=>Number(v.replace(/,/g,'')))),rows=[...document.querySelectorAll('.bcalc-sheet tbody tr')],start=rows.indexOf(e.target.closest('tr')),col=e.target.dataset.cship==='a'?0:1;if(values.some(v=>v.length>2-col||v.some(n=>!Number.isSafeInteger(n)||n<0||n>1000000000))||start+values.length>rows.length)return notify('Paste at most two numeric columns using whole ship counts.',true);window.bcalc=window.bcalc||{a:{},d:{}};values.forEach((line,i)=>line.forEach((n,j)=>{const input=rows[start+i].querySelectorAll('input')[col+j];input.value=n;window.bcalc[input.dataset.cship][input.dataset.ship]=n;}));notify('Spreadsheet counts pasted.');});

