function politicsBriefingHTML(){ensureGalaxyPolitics();return '<section class="diplomatic-briefing"><div class="council-seal" aria-hidden="true"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="33" fill="none" stroke="currentColor" stroke-width="2"/><path d="M21 78Q-2 43 25 15M79 78Q102 43 75 15M25 18L17 29M19 34L12 44M18 50L13 60M23 65L19 74M75 18L83 29M81 34L88 44M82 50L87 60M77 65L81 74" fill="none" stroke="currentColor" stroke-width="3"/><path d="M50 25 55 43 74 43 59 54 64 72 50 61 36 72 41 54 26 43 45 43Z" fill="currentColor" opacity=".75"/></svg></div><div><small>GALACTIC COUNCIL · DIPLOMATIC CHAMBER</small><h3>'+esc(state.politics.banner||'Galaxy council')+'</h3><p>Representation · Cooperation · Governance</p></div><div class="council-office"><small>GALACTIC COMMANDER</small><b>'+esc(state.politics.gc||'Not elected')+'</b><small>CABINET OFFICES</small><b>'+Object.keys(state.politics.ministers||{}).length+'</b></div></section>';}
function galaxyTreasuryBriefingHTML(){const fund=state.galaxyFund,total=Object.keys(RES).reduce((n,k)=>n+(fund[k]||0),0);return '<section class="treasury-briefing"><div><small>GALACTIC TREASURY · RESERVE ALLOCATION</small><h3>Galaxy Fund</h3><p>Contributions finance relief for eligible planets.</p></div><div class="treasury-total"><small>TOTAL RESOURCE UNITS</small><b>'+nfmt(total)+'</b></div><div class="reserve-allocation">'+Object.keys(RES).map(k=>'<div data-resource="'+k+'"><span>'+RES[k].label+'</span><div class="reserve-track"><i style="width:'+(total?100*(fund[k]||0)/total:0)+'%"></i></div><small>'+nfmt(fund[k]||0)+'</small></div>').join('')+'</div></section>';}

function tickerStatusHTML(){const ended=state.tick>=state.roundLength,status=ended?'ROUND ENDED':state.config.tickerStopped?'STOPPED':state.config.tickerPaused?'PAUSED':'RUNNING',tone=ended||state.config.tickerStopped?'stopped':state.config.tickerPaused?'paused':'running',next=tone==='running'?countdown():status==='PAUSED'?'Paused':'—',action=state.tickerLastAction;return '<section class="ticker-live-status '+tone+'"><div class="ticker-status-heading"><span class="ticker-state-dot" aria-hidden="true"></span><strong>'+status+'</strong><small>CURRENT TICKER INFORMATION</small></div><div class="ticker-status-grid"><div><small>CURRENT TICK</small><b>'+state.tick+' / '+state.roundLength+'</b></div><div><small>TICK INTERVAL</small><b>'+nfmt(state.config.tickHours*60)+' minutes</b></div><div><small>NEXT TICK IN</small><b data-ticker-countdown>'+esc(next)+'</b></div><div><small>AUTOMATIC START</small><b>'+esc(state.config.tickerAutoStartAt?new Date(state.config.tickerAutoStartAt).toLocaleString():'Not scheduled')+'</b></div><div><small>LAST PROCESSED TICK</small><b>'+esc(state.lastTickAt?new Date(state.lastTickAt).toLocaleString():'No tick recorded yet')+'</b></div></div>'+(action?'<p class="ticker-action-confirmation" role="status">✓ '+esc(action.message)+' <time>'+new Date(action.at).toLocaleTimeString()+'</time></p>':'')+'</section>';}
function refreshTickerStatusBox(){const box=document.getElementById('tickerStatusBox');if(!box)return;const signature=JSON.stringify([state.tick,state.roundLength,state.config,state.lastTickAt,state.tickerLastAction]);if(box.dataset.signature!==signature){box.dataset.signature=signature;box.innerHTML=tickerStatusHTML();}else{const next=box.querySelector?.('[data-ticker-countdown]');if(next&&!state.config.tickerStopped&&!state.config.tickerPaused&&state.tick<state.roundLength)next.textContent=countdown();}}

function workforceAllocationLimit(){return Math.min(100,50+10*Math.max(0,Math.min(5,state.research.population||0)));}
function validWorkforceAssignments(values){return Object.keys(WORKFORCE_LIMITS).every(k=>Number.isInteger(values[k])&&values[k]>=0&&values[k]<=WORKFORCE_LIMITS[k])&&Object.values(values).reduce((n,v)=>n+v,0)<=workforceAllocationLimit();}
function normalizeWorkforceAssignments(){const keys=Object.keys(WORKFORCE_LIMITS),values=Object.fromEntries(keys.map(k=>[k,Math.max(0,Math.min(WORKFORCE_LIMITS[k],Math.trunc(Number(state.workforce?.[k])||0)))])),total=Object.values(values).reduce((n,v)=>n+v,0),limit=workforceAllocationLimit();if(total>limit){const fractions=keys.map(k=>({k,value:values[k]*limit/total}));for(const x of fractions)values[x.k]=Math.floor(x.value);let remaining=limit-Object.values(values).reduce((n,v)=>n+v,0);for(const x of fractions.sort((a,b)=>(b.value%1)-(a.value%1)))if(remaining-->0)values[x.k]++;}state.workforce=values;}

let orderPageRefreshPending=false;
async function refreshPageAfterOrder(){if(orderPageRefreshPending)return;orderPageRefreshPending=true;save();try{if(typeof sessionStorage!=='undefined')sessionStorage.setItem(SAVE_KEY+'-order-return',JSON.stringify({page:document.querySelector('.page.active')?.id?.slice(5)||'overview',allianceTab,scroll:window.scrollY||0,at:Date.now()}));if(typeof syncPlanetDirectory==='function')await syncPlanetDirectory();save();location.reload();}catch(error){orderPageRefreshPending=false;notify('Order saved. Refresh the page to reload the latest view.',true);}}
if(typeof window.addEventListener==='function')window.addEventListener('load',()=>{if(typeof sessionStorage==='undefined')return;let saved;try{saved=JSON.parse(sessionStorage.getItem(SAVE_KEY+'-order-return')||'null');sessionStorage.removeItem(SAVE_KEY+'-order-return');}catch{return;}if(!saved||Date.now()-saved.at>60000)return;allianceTab=saved.allianceTab||'home';renderAlliance();if(document.getElementById('page-'+saved.page))navigate(saved.page);setTimeout(()=>window.scrollTo({top:saved.scroll||0,behavior:'instant'}),100);notify('Order saved. Page refreshed.');});

function structureCapacityStats(){const built=Object.values(state.buildings).reduce((n,v)=>n+v,0),pending=state.constructionQueue.length+(state.construction?1:0),limit=buildingLimit();return {built,pending,limit,remaining:Math.max(0,limit-built-pending)};}
function affordableStructureCount(id){const d=BUILDINGS[id],room=structureCapacityStats().remaining,stock={...state.resources},start=(state.buildings[id]||0)+state.constructionQueue.filter(o=>o.id===id).length+(state.construction?.id===id?1:0);let count=0;for(;count<room;count++){const n=start+count+1,f=(n**1.25/1000+1)*n,cost=Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,Math.ceil(v*f)]));if(Object.entries(cost).some(([k,v])=>stock[k]<v))break;for(const [k,v] of Object.entries(cost))stock[k]-=v;}return count;}
function structureBonusSummary(id){const owned=state.buildings[id]||0,d=BUILDINGS[id];let total='';if(id.endsWith('Refinery'))total=nfmt(owned*1100)+' base resource units / tick';else if(id==='biodome')total=nfmt(owned*50)+' extra resident places';else if(id==='financeCenter')total='+'+(owned*.5)+'% income';else if(id==='researchLab')total=nfmt(owned*24)+' base RP / tick before workforce modifiers';else if(d.kind==='Factory')total=owned+' production '+(owned===1?'facility':'facilities');const description=id==='biodome'?'+50 housing and +1 resident / tick per dome. Growth research: +'+populationGrowthBonus()+'%. Residents add mining income and CU/RP.':d.desc;return '<span>'+esc(description)+'</span>'+(total?'<small>Current: '+esc(total)+'</small>':'');}
function currentStructuresHTML(){const cap=structureCapacityStats();return '<section class="panel current-structures-panel"><div class="ph"><div class="pt">CURRENT STRUCTURES & BONUSES</div><span class="meta">'+cap.built+' BUILT · '+cap.pending+' IN PROGRESS · '+cap.remaining+' FREE / '+cap.limit+' SLOTS</span></div><div class="table-wrap"><table class="table current-structures-table"><colgroup><col style="width:23%"><col style="width:6%"><col style="width:7%"><col style="width:7%"><col style="width:7%"><col style="width:20%"><col style="width:30%"></colgroup><thead><tr><th>Facility</th><th>Owned</th><th>In progress</th><th>Free slots</th><th>Affordable</th><th>Next build cost</th><th>Bonus / effect</th></tr></thead><tbody>'+Object.entries(BUILDINGS).map(([id,d])=>{const pending=state.constructionQueue.filter(o=>o.id===id).length+(state.construction?.id===id?1:0),cost=buildingCost(id);return '<tr class="structure-register-row"><td data-label="Facility"><div class="structure-register-identity">'+structureGlyph(id)+'<div><b>'+esc(d.name)+'</b><small>'+esc(d.kind)+'</small></div></div></td><td data-label="Owned"><span class="structure-register-number">'+nfmt(state.buildings[id]||0)+'</span></td><td data-label="In progress">'+pending+'</td><td data-label="Free slots">'+cap.remaining+'</td><td data-label="Affordable">'+affordableStructureCount(id)+'</td><td data-label="Next build cost"><div class="structure-register-cost">'+Object.entries(cost).filter(([,n])=>n>0).map(([key,n])=>'<span class="structure-register-price '+esc(key)+'"><span>'+esc(RES[key].label)+'</span><b>'+nfmt(n)+'</b></span>').join('')+'</div></td><td data-label="Bonus / effect"><div class="structure-register-effect"><img src="/assets/structures/'+id+'.svg" loading="lazy" alt="'+esc(d.name)+' illustration"><div>'+structureBonusSummary(id)+'</div></div></td></tr>';}).join('')+'</tbody></table></div><div class="note">Free slots are shared by all facilities, including active and queued builds. Affordable counts are alternatives based on current resources. Infrastructure research increases the shared limit.</div></section>';}

function syncTransferAmountState(){const all=document.getElementById('transferShip')?.value==='group:all',amount=document.getElementById('transferAmount');if(amount){amount.disabled=all;amount.title=all?'All ships in the source fleet will be moved.':'Amount per selected ship type';}}
