function attachAchievementReceipt(quests){const totals={metal:0,crystal:0,eonium:0,research:0,construction:0,population:0,structures:{},roids:{metal:0,crystal:0,eonium:0}},entries=quests.map(q=>{const reward=state.questRewardReceipts?.[q[0]]||questReward(q);totals.population+=reward.population||0;for(const [id,n] of Object.entries(reward.structures||{}))totals.structures[id]=(totals.structures[id]||0)+n;for(const k of ['metal','crystal','eonium','research','construction'])totals[k]+=reward[k]||0;for(const k of ['metal','crystal','eonium'])totals.roids[k]+=reward.roids[k]||0;return {id:q[0],name:q[1],office:QUEST_CATEGORIES.find(c=>c.quests.some(x=>x[0]===q[0]))?.name||'Achievements',medal:'Gold claim medal',reward};});const receipt={entries,totals,medals:entries.length};if(state.news[0])state.news[0].achievementReceipt=receipt;return receipt;}
function achievementReceiptHTML(receipt){const t=receipt.totals,types=[['SETTLERS',t.population||0,''],...Object.entries(t.structures||{}).map(([id,n])=>[BUILDINGS[id].name.toUpperCase(),n,'']),['METAL',t.metal,'metal'],['CRYSTAL',t.crystal,'crystal'],['EONIUM',t.eonium,'eonium'],['RESEARCH POINTS',t.research,''],['CONSTRUCTION UNITS',t.construction,''],['METAL ASTEROIDS',t.roids.metal,'metal'],['CRYSTAL ASTEROIDS',t.roids.crystal,'crystal'],['EONIUM ASTEROIDS',t.roids.eonium,'eonium']];return '<section class="achievement-receipt"><div class="achievement-receipt-banner"><div class="receipt-medal-emblem" aria-hidden="true">'+questMedalIcon(true)+'</div><div><span class="eyebrow">COMMAND HONOURS · REWARD RECEIPT</span><h3>'+ (receipt.entries.length===1?'Achievement claimed!':'Achievements claimed!')+'</h3><p>'+receipt.entries.length+' '+(receipt.entries.length===1?'achievement':'achievements')+' · '+receipt.medals+' '+(receipt.medals===1?'gold claim medal':'gold claim medals')+'</p></div><span class="receipt-sparkle" aria-hidden="true">✦</span></div><div class="receipt-awards">'+receipt.entries.map(e=>'<article><span>'+questMedalIcon(true)+'</span><div><b>'+esc(e.name)+'</b><small>'+esc(e.office)+'</small><small class="receipt-medal-label">'+esc(e.medal)+'</small></div></article>').join('')+'</div><h4>TOTAL REWARDS CLAIMED</h4><div class="receipt-totals">'+types.map(([label,n,resource])=>'<div>'+(resource?'<span class="quest-resource-icon '+resource+'" aria-hidden="true"></span>':'<span class="receipt-point-icon" aria-hidden="true">'+(label==='RESEARCH POINTS'?'RP':'CU')+'</span>')+'<span><small>'+label+'</small><b>+'+nfmt(n||0)+'</b></span></div>').join('')+'</div><p class="receipt-footer">✓ Added to your Bonuses bank. Allocate rewards from Achievements → Bonuses. Gold medals mark claimed achievement rewards.</p></section>';}

function resolveBiodomeDamage(ships,count,previousDamage,population,populationBase=1000){const before=Math.max(0,Math.floor(count||0)),damageBefore=before?Math.max(0,Math.min(999,Math.floor(previousDamage||0))):0,fire=Object.entries(ships).reduce((sum,[id,n])=>sum+(SHIPS[id]?.type==='Struc'?n*(SHIPS[id].guns||1)*(SHIPS[id].damage||0):0),0),damage=Math.min(Math.max(0,before*1000-damageBefore),Math.max(0,Math.floor(fire))),total=damageBefore+damage,destroyed=Math.min(before,Math.floor(total/1000)),after=before-destroyed,damageAfter=after?total%1000:0,populationLost=Math.min(Math.max(0,(population||0)-populationBase),Math.floor(total/20)-Math.floor(damageBefore/20));return {before,after,destroyed,damageBefore,damageAfter,populationLost};}
function allianceWarBonus(target){const declarations=state.alliance.warDeclarations||{},active=(state.alliance.wars||[]).filter(name=>!declarations[name]||state.tick<declarations[name].expiresAt),war=declarations[target];if(active.includes(target))return war?{capture:war.captureBonus,xp:war.xpBonus}:{capture:5,xp:25};return active.length?{capture:-5,xp:-25}:{capture:0,xp:0};}
function expireAllianceWars(){const a=state.alliance;if(!a)return;for(const [name,war] of Object.entries(a.warDeclarations||{}))if(state.tick>=war.expiresAt&&a.wars.includes(name)){a.wars=a.wars.filter(n=>n!==name);addNews('The 48-tick war declared by '+a.name+' against '+name+' has expired.','info');}}
function diplomacyReportHTML(d){const war=d.action==='war',bonus=d.bonus;return '<section class="war-report"><h3>'+esc(d.source)+(war?' declared war against ':' declared peace with ')+esc(d.target)+'</h3><blockquote><b>'+esc(d.source)+' envoy:</b> '+(war?'Our council has sealed the war mandate. The border beacons now mark your fleets as hostile.':'Our council withdraws the war mandate. Let trade lanes reopen under a quiet sky.')+'</blockquote><blockquote><b>'+esc(d.target)+' communications officer:</b> '+(war?'Transmission received. Civilian habitats are being secured; command is placing the defence watch on alert.':'Transmission acknowledged. We have recorded your declaration of peace.')+'</blockquote><div class="war-bonuses">'+(war&&bonus?'<b>Asteroid capture: +'+bonus.capture+' percentage points</b><b>Capture XP: +'+bonus.xp+'%</b><b>Duration: 48 ticks</b>':'<b>No war bonus applies to this peace declaration.</b>')+'</div><small>Fictional diplomatic transcript. '+(war?'Bonuses apply to attacks by '+esc(d.source)+' on '+esc(d.target)+'. Other targets during an active war: −5 capture points and −25% capture XP.':'Peace is declared by the sender; it does not cancel a separate declaration by the other alliance.')+'</small></section>';}

function planetTypeHTML(){const t=planetTypeFor(state);return '<section class="panel planet-type-register"><div class="ph"><div class="pt">01 · PLANETARY SURVEY</div><span class="meta">COLONIAL DEVELOPMENT AUTHORITY</span></div><div class="planet-survey-body"><img src="/assets/planets/'+t.id+'.svg" alt="'+esc(t.name)+' planet"><div><small>'+esc(t.rarity||'Standard')+' · '+esc(t.familyLabel||t.family||'Frontier Worlds')+' · '+esc(t.statsOrigin||'Original gameplay world')+'</small><h3>'+esc(t.name)+'</h3><p>'+esc(t.lore)+'</p><div class="planet-survey-stats">'+[['Ship resource discount',(t.shipCostDiscountPercent||0)+'%'],['Fleet ETA',(t.travelEtaBonus||0)+' ticks'],['Bonus salvage',(t.salvageBonusPercent||0)+'%'],['Habitability',t.habitability+'%'],['Biodiversity',t.biodiversity+'%'],['Moisture',t.moisture+'%'],['Rockiness',t.rockiness+'%'],['Starting residents',nfmt(t.basePopulation)],['Population growth', (t.growthPercent>=0?'+':'')+t.growthPercent+'%']].map(([k,v])=>'<span><small>'+k+'</small><b>'+v+'</b></span>').join('')+'</div><p class="meta">'+populationGrowthRate().toFixed(2)+' residents / tick · '+(state.buildings.biodome||0)+' Biodomes × research '+(1+populationGrowthBonus()/100).toFixed(2)+' × environment '+(1+t.growthPercent/100).toFixed(2)+'</p></div></div></section>';}
function populationDetailHTML(){const cap=populationCapacity(),population=state.population,free=Math.max(0,cap-population),growth=Math.min(free,Math.floor(populationGrowthRate()+(state.populationGrowthCarry||0)+1e-9)),assigned=Object.values(state.workforce).reduce((a,b)=>a+b,0),rows=[['Residents',nfmt(population),'Base colony: '+nfmt(planetBasePopulation(state))],['Housing capacity',nfmt(cap),nfmt(state.buildings.biodome||0)+' Biodomes · +50 each'],['Free housing',nfmt(free),'Growth pauses when full'],['Growth research',nfmt(state.research.demography||0)+' / 5','+20% per level · fractions carried forward'],['Next tick growth','+'+nfmt(growth),populationGrowthRate().toFixed(1)+' residents / tick · +'+populationGrowthBonus()+'% research'],['Population mining bonus','+'+populationIncomeBonus().toFixed(3)+'%','0.001% per resident'],['Population work bonus','+'+populationProductionBonus()+' CU / RP','1 each per full 100 residents'],['Workforce pool',assigned+'% / '+workforceAllocationLimit()+'%','Research '+(state.research.population||0)+' / 5']];return planetTypeHTML()+'<section class="panel population-detail"><div class="ph"><div class="pt">CIVIL POPULATION · COLONY REGISTER</div><span class="meta">LIVE ECONOMY</span></div><div class="population-kpis">'+rows.map(([title,value,note])=>'<article><small>'+title+'</small><b>'+value+'</b><span>'+note+'</span></article>').join('')+'</div><div class="population-housing"><img src="/assets/biodome.svg" alt="Green Ark habitat artwork"><p><b>Green Arks of the Vesper Reach</b><br>Radiation-shielded gardens turn barren ground into living neighbourhoods. Build Biodomes under Construction to house new settlers and expand your mining workforce.</p></div></section>';}

function populationDamageLabel(ship){return ['Cruiser','Battleship'].includes(ship.class)?Number(ship.populationDamage??0.1).toLocaleString('en-US',{maximumFractionDigits:3})+'%':'';}

function havocShipMatrixHTML(){const races=['Terran','Cathaar','Xandathrii','Zikonian','Eitraides'],catalog=Object.fromEntries(races.map(r=>[r,Object.entries(SHIPS).filter(([,d])=>d.race===r).slice(0,10)])),own=catalog[state.race]||catalog.Terran;return '<section class="panel havoc-ship-matrix"><div class="ph"><div class="pt">BASE FLEET · TEN-SHIP RACE MATRIX</div><span class="meta">ONE QUANTITY PER ROW</span></div><div class="table-wrap"><table class="table"><colgroup><col style="width:5%"><col style="width:12%">'+races.map(()=>'<col style="width:16.6%">').join('')+'</colgroup><thead><tr><th>#</th><th>Ships</th>'+races.map(r=>'<th data-ship-race="'+esc(r)+'">'+esc(r)+'</th>').join('')+'</tr></thead><tbody>'+Array.from({length:10},(_,i)=>'<tr><td>'+(i+1)+'</td><td><input id="havocShipSlot-'+i+'" data-havoc-ship-slot="'+i+'" type="number" min="0" max="1000000000" step="1" value="'+(state.fleets.base[own[i]?.[0]]||0)+'" aria-label="Ship quantity for slot '+(i+1)+'"></td>'+races.map(r=>{const d=catalog[r][i]?.[1];return '<td data-ship-race="'+esc(r)+'">'+(d?'<b>'+esc(d.name)+'</b><small>'+esc(d.class)+'</small>':'')+'</td>';}).join('')+'</tr>').join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-confirm-havoc-setup>CONFIRM SETUP</button><span id="havocConfirmationStatus" class="meta" role="status">Confirmation required before Apply to all.</span></div><div class="note">Each amount creates the corresponding ship shown for that planet’s race in its Base fleet. Other fleet slots and active missions retain their ships.</div></section>';}

document.addEventListener('change',e=>{if(e.target.dataset?.field!=='class'||!e.target.dataset.shipstat)return;const input=document.querySelector('[data-shipstat="'+e.target.dataset.shipstat+'"][data-field="populationDamage"]');if(!input)return;const enabled=['Cruiser','Battleship'].includes(e.target.value);input.disabled=!enabled;if(!enabled)input.value='';else if(input.value==='')input.value='0.1';});

function havocMatrixPresent(){return !!document.getElementById('havocShipSlot-0')?.hasAttribute?.('data-havoc-ship-slot');}
function validateHavocShipMatrix(amounts=Array.from({length:10},(_,i)=>Number(document.getElementById('havocShipSlot-'+i)?.value||0)),planets=state.galaxy){if(amounts.length!==10||amounts.some(n=>!Number.isSafeInteger(n)||n<0||n>1000000000))return {ok:false,error:'Enter whole ship quantities between 0 and 1,000,000,000 in all ten rows.'};const races=[...new Set(planets.map(p=>p.player?state.race:p.race))];for(const race of races){const ships=Object.values(SHIPS).filter(d=>d.race===race);for(let i=0;i<10;i++)if(amounts[i]>0&&!ships[i])return {ok:false,error:race+' has no matching ship for row '+(i+1)+'. Nothing was applied.'};}return {ok:true,amounts};}
function havocFormValues(){const allowed=/^(havocTickMinutes|havocPopulation|havocBiodomeDamage|havocResource-(metal|crystal|eonium)|havocRoids-(metal|crystal|eonium)|havocShipSlot-[0-9]|admTech-[a-zA-Z0-9]+|admBuild-[a-zA-Z0-9]+)$/;return Object.fromEntries([...document.querySelectorAll('#adminContent input[id]')].filter(el=>allowed.test(el.id)).map(el=>[el.id,el.value]).sort(([a],[b])=>a.localeCompare(b)));}
function havocSetupSignature(){return JSON.stringify({values:havocFormValues(),planets:state.galaxy.map(p=>[p.id,p.player?state.race:p.race]).sort(([a],[b])=>String(a).localeCompare(String(b)))});}
function havocPresetKey(){return 'starfall-havoc-presets:'+String(state.centralPlayerId||'local');}
function havocSavedSetups(){try{const data=JSON.parse(localStorage.getItem(havocPresetKey())||'[]');return Array.isArray(data)?data.filter(x=>x&&typeof x.id==='string'&&x.values&&typeof x.values==='object').slice(0,5):[];}catch{return [];}}
function havocPresetOptions(){const list=havocSavedSetups();return '<option value="">Choose a previous setup</option>'+list.map((p,i)=>'<option value="'+esc(p.id)+'">'+(i===0?'Latest':'Previous '+i)+' · '+esc(new Date(p.at).toLocaleString())+'</option>').join('');}
function havocPresetControlsHTML(){return '<section class="panel havoc-preset-panel"><div class="ph"><div class="pt">PREVIOUS HAVOC SETUPS</div><span class="meta">LATEST 5 CONFIRMATIONS</span></div><div class="controls"><label class="field" for="havocPresetSelect">Saved setup<select id="havocPresetSelect">'+havocPresetOptions()+'</select></label><button class="btn" data-load-havoc-setup>LOAD SETUP</button><button class="btn primary" data-confirm-havoc-setup>CONFIRM SETUP</button></div><p class="note">Confirm validates the fleet matrix and saves all current controls. The sixth confirmation replaces the oldest of five. Loading only fills the form; confirm and Apply to all to make changes.</p></section>';}
function confirmHavocSetup(){const check=validateHavocShipMatrix();if(!check.ok){state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent=check.error;return notify(check.error,true);}const invalid=[...document.querySelectorAll('#adminContent input[id]')].find(el=>el.type==='number'&&el.checkValidity&&!el.checkValidity());if(invalid)return notify('Check the value for '+(invalid.id||'this field')+'. Nothing was applied.',true);const values=havocFormValues(),at=Date.now(),preset={id:'havoc-'+at+'-'+Math.random().toString(36).slice(2,8),at,values},saved=[preset,...havocSavedSetups()].slice(0,5);localStorage.setItem(havocPresetKey(),JSON.stringify(saved));state.havocConfirmedSetup=havocSetupSignature();save();const select=document.getElementById('havocPresetSelect');if(select){select.innerHTML=havocPresetOptions();select.value=preset.id;}const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Confirmed · setup saved · ready to Apply to all.';notify('Setup confirmed and saved ('+saved.length+' / 5).');}
function loadHavocSetup(){const selected=document.getElementById('havocPresetSelect')?.value,preset=havocSavedSetups().find(x=>x.id===selected);if(!preset)return notify('Select a previous Havoc setup.',true);for(const [id,value] of Object.entries(preset.values)){const el=document.getElementById(id);if(el&&Object.prototype.hasOwnProperty.call(havocFormValues(),id))el.value=String(value);}for(const el of document.querySelectorAll('[data-havoc-research]')){const t=TECH_TREE.find(t=>t.id===el.dataset.havocResearch);if(t)el.checked=Number(document.getElementById('admTech-'+t.id)?.value)===t.max;}state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Saved setup loaded · confirm before applying.';notify('Previous setup loaded. Review and confirm before Apply to all.');}
document.addEventListener('click',e=>{if(e.target.closest('[data-confirm-havoc-setup]'))confirmHavocSetup();if(e.target.closest('[data-load-havoc-setup]'))loadHavocSetup();});
document.addEventListener('input',e=>{if(e.target.closest?.('.havoc-board')&&e.target.id!=='havocPresetSelect'){state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Changed · confirm this setup again before applying.';}});

function shipRaceLegendHTML(){return '<div class="ship-race-legend" aria-label="Race colour key">'+['Terran','Cathaar','Xandathrii','Zikonian','Eitraides'].map(r=>'<span class="race-code-badge" data-ship-race="'+r+'">'+esc(r)+'</span>').join('')+'</div>';}

document.addEventListener('change',e=>{if(e.target.matches?.('[data-havoc-research]')){state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Changed · confirm this setup again before applying.';}});

function earthBattleSalvage(report,target){const home=state.galaxy.find(p=>p.player);if(planetTypeFor(state).name!=="Earth"&&planetTypeFor(target).name!=="Earth")return null;const award={metal:0,crystal:0,eonium:0};for(const [arrived,left] of [[report.attacker,report.survivorsA],[report.defender,report.survivorsD]])for(const [id,n] of Object.entries(arrived||{}))for(const k of Object.keys(award))award[k]+=(n-(left[id]||0))*(SHIP_BASELINE[id]?.cost[k]||0);for(const k of Object.keys(award))award[k]=Math.floor(award[k]*.2);return {award,recipient:planetTypeFor(state).name==="Earth"?home?.id:target.id,status:"Pending central settlement"};}

function bonusBuildingAvailable(id){const gates={lightFactory:['fighter',1],mediumFactory:['frigate',1],heavyFactory:['siege',1],metalRefinery:['core',1],crystalRefinery:['core',1],eoniumRefinery:['core',1],financeCenter:['core',2],waveAmplifier:['scans',1],waveDistorter:['scans',2],structureDefense:['siege',1]};const gate=gates[id];return !!BUILDINGS[id]&&(!gate||(state.research[gate[0]]||0)>=gate[1]);}
function resolveQuestReward(raw){const r={metal:0,crystal:0,eonium:0,research:0,construction:0,population:0,roids:{metal:0,crystal:0,eonium:0},...copy(raw),structures:{}};let slots=Math.max(0,buildingLimit()-Object.values(state.buildings).reduce((a,b)=>a+b,0)-(state.construction?1:0)-(state.constructionQueue?.length||0));for(const [id,n] of Object.entries(raw.structures||{})){const count=bonusBuildingAvailable(id)?Math.min(n,slots):0;if(count)r.structures[id]=count;slots-=count;r.construction+=(n-count)*(BUILDINGS[id]?.cu||0);}return r;}
function applyExtraQuestReward(r,bank){bank.population=(bank.population||0)+(r.population||0);for(const [id,n] of Object.entries(r.structures||{}))state.buildings[id]=(state.buildings[id]||0)+n;}
function initialiseQuestArcs(){const specs={education:['Founding Academy','research:population',[1,2,3,4,5],'Complete workforce training level','researchLab'],defense:['Shield of the Reach','research:corvette',[1,2,3,4,5],'Certify corvette defence level','lightFactory'],treasury:['Reclaim the Trade Lanes','resourcesTotal',[30000,60000,100000,200000,400000,700000,1000000,1500000,2000000,3000000,5000000,7500000,10000000,15000000,20000000],'Hold combined resource reserves of','financeCenter'],development:['Colonial Renewal','population',[1100,1200,1400,1600,1800,2200,2500,3500,4000,5000,6000,7500,9000,12000,15000],'Grow the colony to','biodome'],security:['The Watchful Citadel','guards',[5,10,15,25,40,60,80,100,150,200,300,400,600,800,1000],'Maintain security guards','structureDefense'],chiefs:['Command of the Frontier','xp',[100,250,500,750,1000,1500,2500,4000,6500,10000,15000,20000,30000,45000,60000],'Earn command experience','heavyFactory'],veterans:['Names in the Beacon','xp',[1000,2000,4000,6000,8000,12000,16000,22000,28000,35000,45000,60000,80000,100000,125000],'Record veteran experience','structureDefense'],fleet:['The Far Horizon','shipvalue',[10000,25000,50000,100000,150000,250000,350000,600000,900000,1250000,1750000,2500000,3500000,5000000,7500000],'Commission total fleet value','mediumFactory'],clandestine:['Whispers Beyond the Gate','agents',[5,10,15,25,40,60,80,100,150,200,300,400,600,800,1000],'Maintain covert agents','waveDistorter'],intelligence:['The Listening Constellation','scans',[5,10,20,40,75,125,200,350,600,900,1250,1750,2500,3500,5000],'Archive completed scans','waveAmplifier'],counter:['No Signal Unchallenged','building:waveDistorter',[1,2,3,4,6,8,10,12,20,30,40,60,80,120,150],'Maintain Wave Distorters','waveDistorter'],civilCovert:['Quiet Picket & Glassfall','covert:strike',[2,3,4,7,10,12,20,25,35,50,75,100,150,200,300],'Complete worker bribery operations','waveDistorter'],habitats:['Gardens Against the Void','building:biodome',[2,3,4,7,10,12,20,30,40,60,75,100,150,200,300],'Construct Green Ark habitats','biodome'],alliance:['The Shared Charter','forum:alliance',[1,2,3,5,8,12,18,25,35,50,75,100,150,200,300],'Publish alliance forum dispatches','researchLab'],ticker:['The Beacon Clock','tick',[2,3,6,12,24,48,72,96,120,168,240,336,400,500,600],'Reach active round tick','researchLab']};
for(const c of QUEST_CATEGORIES){for(const q of c.quests){if(q[2]===0&&q[3]!=='offsite')q[2]=Number(q[0].match(/\d+/)?.[0])||1;if(q[3]==='offsite'){const metric=c.id==='security'?'guards':c.id==='veterans'?'xp':c.id==='education'?'forum:galaxy':'mission:Attack';q[3]=metric;q[2]=c.id==='veterans'?Math.max(100,Number(q[0].match(/\d+/)?.[0])||100)*100:c.id==='security'?Math.max(5,Number(q[0].match(/\d+/)?.[0])||5):1;q[1]=c.id==='security'?'Build a security watch of '+q[2]+' guards':c.id==='veterans'?'Honour veterans with '+q[2]+' XP':c.id==='education'?'Publish a founding galaxy dispatch':'Launch an attack to defend the frontier';}}
const [arc,metric,targets,label,structure]=specs[c.id];let stage=0;for(const target of targets){if(c.quests.length>=15)break;if(c.quests.some(q=>q[2]===target&&q[3]===metric))continue;stage++;const tier=Math.min(5,Math.ceil(stage/3)),r={metal:200*tier,crystal:150*tier,eonium:100*tier,research:['education','intelligence','clandestine','counter','civilCovert'].includes(c.id)?100*tier:50*tier,construction:50*tier,roids:{metal:0,crystal:0,eonium:0}};if(['development','habitats','alliance','veterans'].includes(c.id))r.population=5*tier;if(stage%5===0)r.structures={[structure]:1};c.quests.push(['arc-'+c.id+'-'+target,label+' '+target.toLocaleString('en-US'),target,metric,{arc,reward:r,lore:arc+' · Chapter '+stage+'. '+({education:'The academy recovers a sealed curriculum and trains the next generation of colonial specialists.',defense:'Escort beacons reconnect the defence line as shipwrights certify a stronger shield.',treasury:'The treasury restores a lost supply lane and releases a measured recovery warrant.',development:'Civil planners open another district, balancing settlement growth with available housing.',security:'The night watch registers new personnel and protects the colony’s life-support corridors.',chiefs:'Fleet command records the campaign and honours disciplined service to the frontier.',veterans:'A memorial beacon preserves the names of those who held the gates open.',fleet:'Navigation crews extend the command’s reach through newly commissioned vessels.',clandestine:'Encrypted field reports trace a quiet route through hostile intelligence networks.',intelligence:'Listening arrays recover another fragment of the lost Miday transmission.',counter:'The signal bureau closes a compromised channel and strengthens its interference lattice.',civilCovert:'Field organisers report the outcome of their campaign among the industrial districts.',habitats:'A Green Ark district brings sheltered gardens and room for new settlers.',alliance:'Shared dispatches turn isolated commands into a coordinated frontier coalition.',ticker:'The timing bureau marks another interval in the recovery of the Vesper network.'})[c.id]}]);}
if(c.quests.length<15)throw Error('Quest arc incomplete: '+c.id);c.arc=arc;c.shortName=({education:'Education',defense:'Defence',treasury:'Treasury',development:'Development',security:'Planetary Security',chiefs:'Joint Chiefs',veterans:'Veterans',fleet:'Fleet',clandestine:'Clandestine Services',intelligence:'Intelligence',counter:'Counter Intelligence',civilCovert:'Covert Civil Operations',habitats:'Habitat Development',alliance:'Alliance Cooperation',ticker:'Temporal Command'})[c.id];}
const order=['education','development','habitats','treasury','defense','security','fleet','chiefs','veterans','intelligence','counter','clandestine','civilCovert','alliance','ticker'];QUEST_CATEGORIES.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));}
initialiseQuestArcs();

setTimeout(renderQuests,0);

function displayPlanetName(name){return String(name||'').replace(/^\s*of\s+/i,'');}

function rollAvailableLocalWorld(){const used=new Set(state.galaxy.map(p=>p.planetType));const pool=PLANET_TYPES.filter(t=>!t.uniquePerRound||!used.has(t.id));return pool[Math.floor(Math.random()*pool.length)];}

let completeWorldCataloguePromise;function loadCompleteWorldCatalogue(){if(!completeWorldCataloguePromise)completeWorldCataloguePromise=fetch("/planet-catalog.json").then(r=>{if(!r.ok)throw Error("World catalogue unavailable.");return r.json();}).then(types=>{for(const t of types)if(!PLANET_TYPES.some(p=>p.id===t.id))PLANET_TYPES.push(t);window.fullWorldCatalogLoaded=true;return types;}).catch(e=>{completeWorldCataloguePromise=null;throw e;});return completeWorldCataloguePromise;}
